    return this.cacheManager.getOrSet(
      RedisKeys.notificationCount(userId),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Cache recent notifications for user
   */
  async getRecentNotifications(userId: string, factory: () => Promise<any[]>): Promise<any[]> {
    return this.cacheManager.getOrSet(
      RedisKeys.recentNotifications(userId),
      factory,
      CacheTTL.SHORT,
    );
  }

  /**
   * Invalidate notification count cache
   */
  async invalidateNotificationCount(userId: string): Promise<void> {
    await this.cacheManager.delete(RedisKeys.notificationCount(userId));
    this.logger.debug(`Invalidated notification count for user: ${userId}`);
  }

  /**
   * Invalidate recent notifications cache
   */
  async invalidateRecentNotifications(userId: string): Promise<void> {
    await this.cacheManager.delete(RedisKeys.recentNotifications(userId));
    this.logger.debug(`Invalidated recent notifications for user: ${userId}`);
  }

  /**
   * Invalidate all notification cache for user
   */
  async invalidateUserNotificationsCache(userId: string): Promise<void> {
    await this.cacheManager.invalidateByPrefix(`qotes:notifications:${userId}`);
    this.logger.debug(`Invalidated all notification cache for user: ${userId}`);
  }

  /**
   * Warm up notification count
   */
  async warmUpNotificationCount(userId: string, count: number): Promise<void> {
    await this.cacheManager.set(RedisKeys.notificationCount(userId), count, CacheTTL.MEDIUM_SHORT);
    this.logger.debug(`Warmed up notification count for user: ${userId}`);
  }

  /**
   * Warm up recent notifications
   */
  async warmUpRecentNotifications(userId: string, notifications: any[]): Promise<void> {
    await this.cacheManager.set(RedisKeys.recentNotifications(userId), notifications, CacheTTL.SHORT);
    this.logger.debug(`Warmed up recent notifications for user: ${userId}`);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { CacheManagerService } from './cache-manager.service';
import { RedisKeys, CacheTTL } from '../../shared/utils/redis.utils';
import { IQuote } from '../../models/quote.model';

@Injectable()
export class QuoteCacheService {
  private readonly logger = new Logger(QuoteCacheService.name);

  constructor(private readonly cacheManager: CacheManagerService) { }

  /**
   * Cache single quote by ID
   */
  async getQuote(quoteId: string, factory: () => Promise<IQuote>): Promise<IQuote> {
    return this.cacheManager.getOrSet(
      RedisKeys.quote(quoteId),
      factory,
      CacheTTL.LONG,
    );
  }

  /**
   * Cache quote statistics
   */
  async getQuoteStats(quoteId: string, factory: () => Promise<any>): Promise<any> {
    return this.cacheManager.getOrSet(
      RedisKeys.quoteStats(quoteId),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Cache user's quotes with pagination
   */
  async getUserQuotes<T = any>(userId: string, page: number, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.userQuotes(userId, page),
      factory,
      CacheTTL.MEDIUM,
    );
  }

  /**
   * Cache global feed with pagination
   */
  async getGlobalFeed<T = any>(page: number, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.globalFeed(page),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Cache following feed with pagination
   */
  async getFollowingFeed<T = any>(userId: string, page: number, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.followingFeed(userId, page),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Cache discover feed with pagination
   */
  async getDiscoverFeed<T = any>(page: number, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.discoverFeed(page),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Invalidate quote-specific cache
   */
  async invalidateQuoteCache(quoteId: string): Promise<void> {
    await this.cacheManager.invalidateQuoteCache(quoteId);
    this.logger.debug(`Invalidated cache for quote: ${quoteId}`);
  }

  /**
   * Invalidate user's quotes cache
   */
  async invalidateUserQuotesCache(userId: string): Promise<void> {
    await this.cacheManager.invalidateByPrefix(`qotes:user:quotes:${userId}`);
    this.logger.debug(`Invalidated quotes cache for user: ${userId}`);
  }

  /**
   * Invalidate all feed caches
   */
  async invalidateFeedCaches(): Promise<void> {
    await this.cacheManager.invalidateByPrefix('qotes:feed:global:');
    await this.cacheManager.invalidateByPrefix('qotes:feed:following:');
    await this.cacheManager.invalidateByPrefix('qotes:feed:discover:');
    this.logger.debug('Invalidated all feed caches');
  }

  /**
   * Invalidate following feed for specific user
   */
  async invalidateFollowingFeed(userId: string): Promise<void> {
    await this.cacheManager.invalidateByPrefix(`qotes:feed:following:${userId}`);
    this.logger.debug(`Invalidated following feed for user: ${userId}`);
  }

  /**
   * Warm up quote cache after creation/update
   */
  async warmUpQuoteCache(quote: IQuote): Promise<void> {
    await this.cacheManager.set(RedisKeys.quote(quote._id.toString()), quote, CacheTTL.LONG);
    this.logger.debug(`Warmed up cache for quote: ${quote._id}`);
  }

  /**
   * Batch warm up quotes
   */
  async warmUpQuotesCache(quotes: IQuote[]): Promise<void> {
    const promises = quotes.map(quote =>
      this.warmUpQuoteCache(quote)
    );
    await Promise.allSettled(promises);
    this.logger.debug(`Warmed up cache for ${quotes.length} quotes`);
  }
}

import mongoose from "mongoose";
import {
  redis,
  RedisKeys,
  cacheGet,
  cacheHGetAll,
} from "../../shared/utils/redis.utils";
import Reaction from "../../models/reaction.model";

const CACHE_TTL_SECONDS = 3600;

interface ReactionBreakdown {
  breakdown: Record<string, number>;
  total: number;
}

async function getReactionBreakdown(
  quoteId: string,
): Promise<ReactionBreakdown> {
  try {
    const [breakdown, total] = await Promise.all([
      cacheHGetAll(RedisKeys.reactionBreakdown(quoteId)),
      cacheGet(RedisKeys.reactionTotal(quoteId)),
    ]);

    if (!total || Object.keys(breakdown).length === 0) {
      const agg = await Reaction.aggregate([
        { $match: { quoteId: new mongoose.Types.ObjectId(quoteId) } },
        { $group: { _id: "$type", count: { $sum: 1 } } },
      ]);

      const repairedBreakdown: Record<string, number> = {};
      let repairedTotal = 0;
      agg.forEach((r: any) => {
        repairedBreakdown[r._id] = r.count;
        repairedTotal += r.count;
      });

      if (repairedTotal > 0) {
        await redis
          .pipeline()
          .hmset(RedisKeys.reactionBreakdown(quoteId), repairedBreakdown)
          .set(RedisKeys.reactionTotal(quoteId), repairedTotal)
          .expire(RedisKeys.reactionBreakdown(quoteId), CACHE_TTL_SECONDS)
          .expire(RedisKeys.reactionTotal(quoteId), CACHE_TTL_SECONDS)
          .exec();
      }

      return { breakdown: repairedBreakdown, total: repairedTotal };
    }

    return {
      breakdown: breakdown as unknown as Record<string, number>,
      total: Number(total || 0),
    };
  } catch {
    return { breakdown: {}, total: 0 };
  }
}

async function atomicUpdateCache(
  quoteId: string,
  type: string,
  delta: number,
  oldType?: string,
): Promise<any> {
  try {
    return await (redis as any).updateReaction(
      RedisKeys.reactionBreakdown(quoteId),
      RedisKeys.reactionTotal(quoteId),
      type,
      delta,
      oldType || "none",
    );
  } catch {
    return null;
  }
}

export { getReactionBreakdown, atomicUpdateCache };

import { Injectable, Logger } from '@nestjs/common';
import { CacheManagerService } from './cache-manager.service';
import { RedisKeys, CacheTTL } from '../../shared/utils/redis.utils';

@Injectable()
export class SearchCacheService {
  private readonly logger = new Logger(SearchCacheService.name);

  constructor(private readonly cacheManager: CacheManagerService) { }

  /**
   * Cache search results for users
   */
  async getUserSearchResults<T = any>(query: string, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.searchResults(query, 'users'),
      factory,
      CacheTTL.SHORT,
    );
  }

  /**
   * Cache search results for quotes
   */
  async getQuoteSearchResults<T = any>(query: string, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.searchResults(query, 'quotes'),
      factory,
      CacheTTL.SHORT,
    );
  }

  /**
   * Cache search results for hashtags
   */
  async getHashtagSearchResults<T = any>(query: string, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.searchResults(query, 'hashtags'),
      factory,
      CacheTTL.SHORT,
    );
  }

  /**
   * Cache global search results
   */
  async getGlobalSearchResults<T = any>(query: string, factory: () => Promise<T>): Promise<T> {
    return this.cacheManager.getOrSet(
      RedisKeys.searchResults(query, 'global'),
      factory,
      CacheTTL.SHORT,
    );
  }

  /**
   * Cache trending hashtags
   */
  async getTrendingHashtags(factory: () => Promise<any[]>): Promise<any[]> {
    return this.cacheManager.getOrSet(
      RedisKeys.trendingHashtags(),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Invalidate search results for a specific query
   */
  async invalidateSearchResults(query: string): Promise<void> {
    await this.cacheManager.invalidateByPrefix(`qotes:search:${query}`);
    this.logger.debug(`Invalidated search results for query: ${query}`);
  }

  /**
   * Invalidate all search cache
