    await this.cacheManager.delete(RedisKeys.trendingHashtags());
    this.logger.debug('Invalidated trending hashtags cache');
  }

  /**
   * Warm up trending hashtags cache
   */
  async warmUpTrendingHashtags(hashtags: any[]): Promise<void> {
    await this.cacheManager.set(RedisKeys.trendingHashtags(), hashtags, CacheTTL.MEDIUM_SHORT);
    this.logger.debug('Warmed up trending hashtags cache');
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { CacheManagerService } from './cache-manager.service';
import { RedisKeys, CacheTTL } from '../../shared/utils/redis.utils';
import { IUser } from '../../models/user.model';

@Injectable()
export class UserCacheService {
  private readonly logger = new Logger(UserCacheService.name);

  constructor(private readonly cacheManager: CacheManagerService) { }

  /**
   * Cache user profile data
   */
  async getUserProfile(userId: string, factory: () => Promise<IUser>): Promise<IUser> {
    return this.cacheManager.getOrSet(
      RedisKeys.userProfile(userId),
      factory,
      CacheTTL.MEDIUM_LONG,
    );
  }

  /**
   * Cache user statistics
   */
  async getUserStats(userId: string, factory: () => Promise<any>): Promise<any> {
    return this.cacheManager.getOrSet(
      RedisKeys.userStats(userId),
      factory,
      CacheTTL.MEDIUM_SHORT,
    );
  }

  /**
   * Cache user's followers list
   */
  async getUserFollowers(userId: string, factory: () => Promise<string[]>): Promise<string[]> {
    return this.cacheManager.getOrSet(
      RedisKeys.userFollowers(userId),
      factory,
      CacheTTL.LONG,
    );
  }

  /**
   * Cache user's following list
   */
  async getUserFollowing(userId: string, factory: () => Promise<string[]>): Promise<string[]> {
    return this.cacheManager.getOrSet(
      RedisKeys.userFollowing(userId),
      factory,
      CacheTTL.LONG,
    );
  }

  /**
   * Cache user preferences
   */
  async getUserPreferences(userId: string, factory: () => Promise<any>): Promise<any> {
    return this.cacheManager.getOrSet(
      RedisKeys.userPreferences(userId),
      factory,
      CacheTTL.VERY_LONG,
    );
  }

  /**
   * Cache suggested users for a user
   */
  async getSuggestedUsers(userId: string, factory: () => Promise<any[]>): Promise<any[]> {
    return this.cacheManager.getOrSet(
      RedisKeys.suggestedUsers(userId),
      factory,
      CacheTTL.MEDIUM,
    );
  }

  /**
   * Invalidate all user-related cache
   */
  async invalidateUserCache(userId: string): Promise<void> {
    await this.cacheManager.invalidateUserCache(userId);
    this.logger.debug(`Invalidated cache for user: ${userId}`);
  }

  /**
   * Warm up user cache on login
   */
  async warmUpUserCache(userId: string, data: {
    profile?: IUser;
    stats?: any;
    followers?: string[];
    following?: string[];
  }): Promise<void> {
    const promises: Promise<any>[] = [];

    if (data.profile) {
      promises.push(
        this.cacheManager.set(RedisKeys.userProfile(userId), data.profile, CacheTTL.MEDIUM_LONG)
      );
    }

    if (data.stats) {
      promises.push(
        this.cacheManager.set(RedisKeys.userStats(userId), data.stats, CacheTTL.MEDIUM_SHORT)
      );
    }

    if (data.followers) {
      promises.push(
        this.cacheManager.set(RedisKeys.userFollowers(userId), data.followers, CacheTTL.LONG)
      );
    }

    if (data.following) {
      promises.push(
        this.cacheManager.set(RedisKeys.userFollowing(userId), data.following, CacheTTL.LONG)
      );
    }

    await Promise.allSettled(promises);
    this.logger.debug(`Warmed up cache for user: ${userId}`);
  }
}

import { kafka } from "../config/kafka.config";
import { Producer, Consumer, KafkaMessage } from "kafkajs";

const producer: Producer = kafka.producer();
const consumer: Consumer = kafka.consumer({
  groupId: "universal-dlq-replayer",
});

const replay = async (dlqTopic: string, targetTopic: string): Promise<void> => {
  if (!dlqTopic || !targetTopic) {
    console.error(
      "❌ Usage: node universal-replayer.js <dlqTopic> <targetTopic>",
    );
    process.exit(1);
  }

  try {
    await producer.connect();
    await consumer.connect();

    await consumer.subscribe({ topic: dlqTopic, fromBeginning: true });

    console.log(`🔄 REPLAY START: [${dlqTopic}] ——> [${targetTopic}]`);

    await consumer.run({
      eachMessage: async ({ message }: { message: KafkaMessage }) => {
        try {
          await producer.send({
            topic: targetTopic,
            messages: [
              {
                key: message.key,
                value: message.value,
                headers: {
                  ...message.headers,
                  replayedAt: Date.now().toString(),
                  originalDlq: dlqTopic,
                },
              },
            ],
          });

          console.log(`✅ [${message.key}] Replayed to ${targetTopic}`);
        } catch (sendErr: any) {
          console.error(
            `❌ Failed to send message ${message.key}:`,
            sendErr.message,
          );
        }
      },
    });
  } catch (err: any) {
    console.error("❌ Replayer Crash:", err.message);
  }
};

const [, , source, target] = process.argv;
void replay(source, target);

import { transporter } from "../../config/nodemailer.config";
import logger from "../../shared/utils/logger.util";

interface EmailOptions {
  to: string;
  subject: string;
  text?: string;
  html?: string;
}

const sendEmail = async ({ to, subject, text, html }: EmailOptions) => {
  if (!to) {
    throw new Error("Email recipient is required");
  }

  const mailOptions = {
    from: process.env.EMAIL,
    to,
    subject,
    text: text || html,
    html: html || text,
  };

  try {
    const result = await transporter.sendMail(mailOptions);
    logger.info("Email sent", {
      service: "email-service",
      to,
      subject,
      messageId: result.messageId,
    });
    return result;
  } catch (error: any) {
    logger.error("Failed to send email", {
      service: "email-service",
      to,
      subject,
      error: error.message,
    });
    throw error;
  }
};

export { sendEmail };

import cloudinary from "../../config/cloudinary.config";
import { promisify } from "util";
import { unlink } from "fs";
// unlinkAsync intentionally removed since not used; keep imports minimal

interface CloudinaryService {
  getPublicIdFromUrl: (imageUrl: string, folderName?: string) => string | null;
  uploadImage: (filePath: string, folderName?: string) => Promise<string>;
  deleteImage: (publicId: string) => Promise<void>;
}

const cloudinaryService: CloudinaryService = {
  /**
   * Extracts the Public ID from a full Cloudinary URL based on the folder structure.
   * @param {string} imageUrl - The full URL of the image.
   * @param {string} folderName - The Cloudinary folder (e.g., 'quotes-app/avatars').
   * @returns {string | null} - The Public ID, or null if the URL doesn't match the expected structure.
   */
  getPublicIdFromUrl: (
    imageUrl: string,
    folderName = "quotes-app/avatars",
  ): string | null => {
    const folderEscaped = folderName.replace(/[\/\.]/g, "\\$&");
    const regex = new RegExp(`${folderEscaped}/([^/]+)\\.`, "i");
    const match = imageUrl.match(regex);
    return match ? match[1] : null;
  },

  /**
   * Uploads a file to Cloudinary in the specified folder and retrieves the URL.
   * @param {string} filePath - The temporary path of the file saved by Multer.
   * @param {string} folderName - The Cloudinary folder (e.g., 'qotes-app/avatars').
   * @returns {string}
   */
  uploadImage: async (
    filePath: string,
    folderName = "qotes-app/avatars",
  ): Promise<string> => {
    try {
      const result = await cloudinary.uploader.upload(filePath, {
        folder: folderName,
        transformation: [
          { width: 300, height: 300, crop: "fill", gravity: "face" },
        ],
        resource_type: "image",
      });

      return result.secure_url;
    } catch (error) {
      console.error("Cloudinary Upload Error:", error);
      throw error;
    }
  },

  /**
   * Deletes an image from Cloudinary using its Public ID.
   * @param {string} publicId - The Public ID of the image to delete.
   */
  deleteImage: async (publicId: string): Promise<void> => {
    try {
      const result = await cloudinary.uploader.destroy(publicId);
      if (result.result !== "ok") {
        console.warn(
          `Cloudinary deletion failed for ID ${publicId}: ${result.result}`,
        );
      }
    } catch (error) {
      console.error(`Cloudinary deletion error for ID ${publicId}:`, error);
    }
  },
};

export default cloudinaryService;

import mongoose from "mongoose";
import { Schema, Document } from "mongoose";
import {
  NOTIFICATION_TYPES,
  REFERENCE_TYPES,
} from "../modules/notifications/notification.constants";

interface INotification extends Document {
  recipient: mongoose.Types.ObjectId;
  sender: mongoose.Types.ObjectId;
  type: string;
  message: string;
  referenceId?: mongoose.Types.ObjectId;
  referenceType?: string;
  metadata?: Map<string, any>;
  isRead: boolean;
  isDeleted: boolean;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Notification Schema
 * Represents a notification in the system
 */
const NotificationSchema = new Schema<INotification>(
  {
    _id: { type: Schema.Types.ObjectId, auto: true },
    recipient: {
      type: Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },
    sender: {
      type: Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },
    type: {
      type: String,
      required: true,
      enum: Object.values(NOTIFICATION_TYPES),
      index: true,
    },
    message: {
      type: String,
      required: true,
      maxlength: 200,
    },
    referenceId: {
      type: Schema.Types.ObjectId,
      index: true,
    },
    referenceType: {
      type: String,
      enum: Object.values(REFERENCE_TYPES),
      index: true,
    },
    metadata: {
      type: Map,
      of: Schema.Types.Mixed,
      default: {},
    },
    isRead: {
      type: Boolean,
      default: false,
      index: true,
    },
    isDeleted: {
      type: Boolean,
      default: false,
      index: true,
    },
    createdAt: {
      type: Date,
      default: Date.now,
      index: true,
    },
    updatedAt: {
      type: Date,
      default: Date.now,
    },
  },
  {
    timestamps: true,
  },
);

// Single indexes for common queries
NotificationSchema.index({ recipient: 1 });
NotificationSchema.index({ sender: 1 });
NotificationSchema.index({ type: 1 });
NotificationSchema.index({ referenceId: 1 });
NotificationSchema.index({ referenceType: 1 });
NotificationSchema.index({ isRead: 1 });
NotificationSchema.index({ isDeleted: 1 });
NotificationSchema.index({ createdAt: 1 });

// Compound indexes for optimized queries
NotificationSchema.index({ recipient: 1, createdAt: -1 }); // User's notifications in chronological order
NotificationSchema.index({ recipient: 1, isRead: 1, createdAt: -1 }); // Unread notifications
NotificationSchema.index({ recipient: 1, isDeleted: 1, createdAt: -1 }); // Exclude deleted notifications

// TTL index for automatic cleanup (90 days)
// Commented out by default - enable if needed
// NotificationSchema.index({ createdAt: 1 }, { expireAfterSeconds: 7776000 }); // 90 days in seconds

// Pre-save middleware to update updatedAt
NotificationSchema.pre("save", function (next) {
  this.updatedAt = new Date();
  next();
});

// Pre-update middleware to update updatedAt
NotificationSchema.pre("findOneAndUpdate", function (next) {
  this.set({ updatedAt: new Date() });
  next();
});

const Notification = mongoose.model<INotification>("Notification", NotificationSchema);

export default Notification;
export { NotificationSchema, INotification };

import { Injectable } from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";
import mongoose from "mongoose";

import User, { IUser } from "../../models/user.model";
import Quote, { IQuote } from "../../models/quote.model";
import {
  buildCompoundCursorQuery,
  processPaginatedResults,
} from "../../shared/utils/cursor.util";

@Injectable()
export class AdminService {
  constructor(
    @InjectModel("User") private readonly userModel: Model<IUser>,
    @InjectModel("Quote") private readonly quoteModel: Model<IQuote>,
  ) {}

  async getAllUsers({
    cursor = null,
    limit = 20,
  }: {
    cursor?: any;
    limit?: number;
  }) {
    const query: any = {};

    if (cursor) {
      Object.assign(
        query,
        buildCompoundCursorQuery(cursor, ["createdAt", "_id"], [-1, 1]),
      );
    }

    const users = await this.userModel
      .find(query)
      .sort({ createdAt: -1, _id: 1 })
      .limit(limit + 1)
      .select("-password -__v")
      .lean();

    const { data, pagination } = processPaginatedResults(users, limit, [
      "createdAt",
      "_id",
    ]);

    return {
      users: data,
      pagination,
    };
  }

  async getHiddenQuotes({
    cursor = null,
    limit = 20,
  }: {
    cursor?: any;
    limit?: number;
  }) {
    const query: any = { isHiddenBySystem: true };

    if (cursor) {
      Object.assign(
        query,
        buildCompoundCursorQuery(cursor, ["createdAt", "_id"], [-1, 1]),
      );
    }

    const quotes = await this.quoteModel
      .find(query)
      .sort({ createdAt: -1, _id: 1 })
      .limit(limit + 1)
      .populate("creator", "username email createdAt")
      .lean();

    const { data, pagination } = processPaginatedResults(quotes, limit, [
      "createdAt",
      "_id",
    ]);

    return {
      quotes: data,
      pagination,
    };
  }
}

import {
  Controller,
  Post,
  Body,
  Req,
  Res,
  Param,
  UseGuards,
  HttpCode,
  HttpStatus,
  UseInterceptors,
} from "@nestjs/common";
import { Response } from "express";
import { Throttle } from "@nestjs/throttler";
import { FileInterceptor } from "@nestjs/platform-express";
import { diskStorage } from "multer";
import { extname } from "path";
import { AuthService } from "./auth.service";
import { AuthenticatedRequest } from "../../shared/interfaces/authenticated-request.interface";
import { JwtAuthGuard } from "./guards/jwt-auth.guard";
import { ResponseInterceptor } from "../../shared/interceptors/response.interceptor";
import bcrypt from "bcryptjs";

// Multer configuration for file uploads
const multerConfig = {
  storage: diskStorage({
    destination: "./uploads",
    filename: (req: any, file: any, cb: any) => {
      const randomName = Array(32)
        .fill(null)
        .map(() => Math.round(Math.random() * 16).toString(16))
        .join("");
      cb(null, `${randomName}${extname(file.originalname)}`);
    },
