@Controller("auth")
@UseInterceptors(ResponseInterceptor)
export class AuthController {
  constructor(private authService: AuthService) { }

  @Post("login")
  @Throttle({ default: { limit: 5, ttl: 60000 } })
  @HttpCode(HttpStatus.OK)
  async login(@Req() req: AuthenticatedRequest, @Res() res: Response) {
    const { identifier, password } = req.body;

    const result = await this.authService.login(identifier, password);

    if (!result) {
      throw new Error("Invalid credentials");
    }

    res.cookie("refreshToken", result.refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      maxAge: 7 * 24 * 60 * 60 * 1000,
    });

    return res.status(HttpStatus.OK).json({
      success: true,
      statusCode: HttpStatus.OK,
      message: "Login successful",
      data: {
        accessToken: result.accessToken,
        userId: result.userId,
      },
    });
  }

  @Post("signup")
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @UseInterceptors(FileInterceptor("avatar", multerConfig))
  async signup(@Req() req: AuthenticatedRequest) {
    const { username, email, password, firstName, lastName, bio } = req.body;
    const avatarFile = req.file || null;

    const existingUser =
      await this.authService.findUserByUsernameOrEmail(username);

    if (existingUser) {
      throw new Error("Username already exists");
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    await this.authService.saveUser(
      username,
      email,
      hashedPassword,
      firstName,
      lastName,
      bio,
      avatarFile,
    );

    return {
      success: true,
      statusCode: HttpStatus.CREATED,
      message: "User registered successfully",
      data: {},
    };
  }

  @Post("logout")
  @HttpCode(HttpStatus.OK)
  async logout(@Req() req: AuthenticatedRequest, @Res() res: Response) {
    const refreshToken = req.cookies.refreshToken;

    if (refreshToken) {
      await this.authService.deleteRefreshToken(refreshToken);
    }

    res.clearCookie("refreshToken");
    return res.status(HttpStatus.OK).json({
      success: true,
      statusCode: HttpStatus.OK,
      message: "Logged out successfully",
      data: {},
    });
  }

  @Post("refresh")
  @Throttle({ default: { limit: 10, ttl: 60000 } })
  @HttpCode(HttpStatus.OK)
  async refresh(@Req() req: AuthenticatedRequest) {
    const refreshToken = req.cookies.refreshToken;

    if (!refreshToken) {
      throw new Error("Refresh token not found");
    }

    const { accessToken } =
      await this.authService.refreshAccessToken(refreshToken);

    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "Token refreshed successfully",
      data: { accessToken },
    };
  }

  @Post("forgot-password")
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @HttpCode(HttpStatus.OK)
  async forgotPassword(@Body() body: { email: string }) {
    const { email } = body;
    const result = await this.authService.generateResetTokenAndSendEmail(email);

    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: result.message,
      data: {},
    };
  }

  @Post("forgotpassword/:userId/:token")
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @HttpCode(HttpStatus.OK)
  async resetPassword(
    @Param("userId") userId: string,
    @Param("token") token: string,
    @Body() body: { newPassword: string; cnfPassword: string },
  ) {
    const { newPassword, cnfPassword } = body;
    const result = await this.authService.resetPasswordWithToken(
      userId,
      token,
      newPassword,
      cnfPassword,
    );

    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: result.message,
      data: {},
    };
  }

  @Post("update-password")
  @UseGuards(JwtAuthGuard)
  @Throttle({ default: { limit: 3, ttl: 60000 } })
  @HttpCode(HttpStatus.OK)
  async updatePassword(
    @Req() req: AuthenticatedRequest,
    @Res() res: Response,
    @Body()
    body: { oldPassword: string; newPassword: string; confirmPassword: string },
  ) {
    const userId = req.user?.userId;
    const { oldPassword, newPassword, confirmPassword } = body;

    const result = await this.authService.updateUserPassword(
      userId,
      oldPassword,
      newPassword,
      confirmPassword,
    );

    res.clearCookie("refreshToken");

    return res.status(HttpStatus.OK).json({
      success: true,
      statusCode: HttpStatus.OK,
      message: result.message,
      data: {},
    });
  }
}

import {
  Injectable,

  UnauthorizedException,
  NotFoundException,
  BadRequestException,
} from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";
import { JwtService } from "@nestjs/jwt";
import { ConfigService } from "@nestjs/config";
import { promises as fs } from "fs";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";

import User, { IUser } from "../../models/user.model";
import Token, { IToken } from "../../models/token.model";
import { forgotPasswordLink } from "../../infrastructure/mailer/forgotPasswordMailer";
import { Inject } from "@nestjs/common";

@Injectable()
export class AuthService {
  constructor(
    @InjectModel(User.name) private userModel: Model<IUser>,
    @InjectModel(Token.name) private tokenModel: Model<IToken>,
    private jwtService: JwtService,
    private configService: ConfigService,
    @Inject("CLOUDINARY_SERVICE") private cloudinaryService: any,
    @Inject("KAFKA_PRODUCER") private kafkaProducer: any,
  ) { }

  async findUserByUsernameOrEmail(identifier: string) {
    return await this.userModel
      .findOne({
        $or: [{ username: identifier }, { email: identifier }],
      })
      .select("+password");
  }

  async login(identifier: string, password: string) {
    const user = await this.findUserByUsernameOrEmail(identifier);
    if (!user) return null;

    const isValidPassword = await bcrypt.compare(password, user.password);
    if (!isValidPassword) return null;

    const REFRESH_SECRET = this.configService.get("REFRESH_SECRET");

    const payload = {
      userId: user._id,
      username: user.username,
    };

    const accessToken = this.jwtService.sign(payload, { expiresIn: "25m" });
    const refreshToken = jwt.sign({ userId: user._id }, REFRESH_SECRET || "", {
      expiresIn: "7d",
    });

    await this.saveRefreshToken(user._id.toString(), refreshToken);

    try {
      await this.kafkaProducer.send({
        topic: "auth-events",
        messages: [
          {
            key: user._id.toString(),
            value: JSON.stringify({ userId: user._id, action: "login_warmup" }),
          },
        ],
      });
    } catch (kafkaErr: any) {
      console.error("Cache warm-up trigger failed:", kafkaErr);
    }

    return {
      accessToken,
      refreshToken,
      userId: user._id,
    };
  }

  async saveUser(
    username: string,
    email: string,
    hashedPassword: string,
    firstName: string,
    lastName: string,
    bio: string,
    avatarFile: any,
  ) {
    let avatarUrl = null;
    let filePath = avatarFile ? avatarFile.path : null;

    try {
      if (avatarFile) {
        avatarUrl = await this.cloudinaryService.uploadImage(filePath);
      }

      const newUser = new this.userModel({
        username,
        email,
        password: hashedPassword,
        firstName,
        lastName,
        bio,
        avatarUrl: avatarUrl,
      });

      const savedUser = await newUser.save();

      if (filePath) await fs.unlink(filePath);

      return savedUser;
    } catch (error: any) {
      if (filePath) {
        await fs
          .unlink(filePath)
          .catch((err) =>
            console.error("Cleanup error after service failure:", err),
          );
      }
      throw error;
    }
  }

  async saveRefreshToken(userId: string, token: string) {
    await this.tokenModel.deleteMany({ userId: userId });
    const newToken = new this.tokenModel({ userId, refreshToken: token });
    return await newToken.save();
  }

  async savePasswordResetToken(userId: string, token: string, expiresAt: Date) {
    const resetToken = new this.tokenModel({
      userId,
      passwordResetToken: token,
      expiresAt,
    });
    return await resetToken.save();
  }

  async deleteRefreshToken(token: string) {
    return await this.tokenModel.deleteOne({ refreshToken: token });
  }

  async findToken(token: string) {
    return await this.tokenModel.findOne({ refreshToken: token });
  }

  async findUserById(userId: string) {
    return await this.userModel.findById(userId).select("+password");
  }

  async refreshAccessToken(refreshToken: string) {
    let decoded: any;
    const REFRESH_SECRET = this.configService.get("REFRESH_SECRET");

    try {
      decoded = jwt.verify(refreshToken, REFRESH_SECRET || "");
    } catch {
      throw new UnauthorizedException("Expired or invalid refresh token");
    }

    const userId = decoded.userId;

    const tokenRecord = await this.findToken(refreshToken);
    if (!tokenRecord || tokenRecord.userId.toString() !== userId) {
      throw new UnauthorizedException("Invalid refresh token state");
    }

    const user = await this.findUserById(userId);
    if (!user) {
      throw new UnauthorizedException("User not found");
    }

    const newAccessToken = this.jwtService.sign(
      { userId: user._id, username: user.username },
      { expiresIn: "15m" },
    );

    return { accessToken: newAccessToken };
  }

  async generateResetTokenAndSendEmail(email: string) {
    const user = await this.userModel.findOne({ email }).select("+password");

    if (!user) {
      return { success: true, message: "If account exists, email sent" };
    }
    const JWT_SECRET = this.configService.get("JWT_SECRET");
    const LOCALHOST =
      this.configService.get("LOCALHOST") || "http://localhost:3030";
    const secret = JWT_SECRET + user.password;

    const payload = {
      email: user.email,
      id: user._id,
    };

    const token = jwt.sign(payload, secret, {
      expiresIn: "15m",
    });

    const link = `${LOCALHOST}/forgotpassword/${user._id}/${token}`;

    await forgotPasswordLink(user.email, link);

    return {
      success: true,
      message: "A password reset link has been sent to your email",
    };
  }

  async resetPasswordWithToken(
    userId: string,
    token: string,
    newPassword: string,
    cnfPassword: string,
  ) {
    if (newPassword !== cnfPassword) {
      throw new BadRequestException("Passwords didn't match");
    }

    const validUser = await this.userModel
      .findOne({ _id: userId })
      .select("+password");

    if (!validUser) {
      throw new NotFoundException("Invalid reset link. User not found.");
    }

    const JWT_SECRET = this.configService.get("JWT_SECRET");
    const secret = JWT_SECRET + validUser.password;
    let payload: any;
    try {
      payload = jwt.verify(token, secret);
    } catch {
      throw new BadRequestException(
        "Password reset link is invalid or has expired",
      );
    }

    const hashPassword = await bcrypt.hash(newPassword, 10);

    const user = await this.userModel.findOneAndUpdate(
      { _id: payload.id, email: payload.email },
      { password: hashPassword },
      { new: true },
    );

    if (!user) {
      throw new NotFoundException("User not found during update");
    }

    return { success: true, message: "Password updated successfully" };
  }

  async updateUserPassword(
    userId: string,
    oldPassword: string,
    newPassword: string,
    confirmPassword: string,
  ) {
    const user = await this.userModel.findById(userId).select("+password");

    if (!user) {
      throw new NotFoundException("User account not found.");
    }

    const isMatch = await bcrypt.compare(oldPassword, user.password);

    if (!isMatch) {
      throw new BadRequestException("Current password incorrect.");
    }
    if (newPassword !== confirmPassword) {
      throw new BadRequestException("New passwords do not match.");
    }
    const hashedNewPassword = await bcrypt.hash(newPassword, 10);

    await this.userModel.findByIdAndUpdate(
      userId,
      { $set: { password: hashedNewPassword } },
      { new: true },
    );

    await this.tokenModel.deleteMany({ userId: userId });

    return {
      success: true,
      message: "Password updated successfully. Please log in again.",
    };
  }
}

import { Injectable, UnauthorizedException } from "@nestjs/common";
import { PassportStrategy } from "@nestjs/passport";
import { ExtractJwt, Strategy } from "passport-jwt";
import { ConfigService } from "@nestjs/config";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";
import User, { IUser } from "../../../models/user.model";

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    private configService: ConfigService,
    @InjectModel(User.name) private userModel: Model<IUser>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.get("JWT_SECRET"),
    });
  }

  async validate(payload: any) {
    const user = await this.userModel
      .findById(payload.userId)
      .select("-password");
    if (!user) {
      throw new UnauthorizedException("User not found");
    }
    return { userId: user._id, username: user.username, id: user._id };
  }
}

import {
  Injectable,
  UnauthorizedException,
} from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";

import Collection, { ICollection } from "../../models/collections.model";
import CollectionItem, {
  ICollectionItem,
} from "../../models/collectionItem.model";
import Quote, { IQuote } from "../../models/quote.model";
import {
  buildCursorQuery,
  processPaginatedResults,
} from "../../shared/utils/cursor.util";
import { CollectionsCacheService } from "../../infrastructure/cache/collections.cache";
import { CacheInvalidationService } from "../../infrastructure/cache/cache-invalidation.service";

@Injectable()
export class CollectionsService {
  constructor(
    @InjectModel(Collection.name) private collectionModel: Model<ICollection>,
    @InjectModel(CollectionItem.name)
    private collectionItemModel: Model<ICollectionItem>,
    @InjectModel(Quote.name) private quoteModel: Model<IQuote>,
    private readonly collectionsCache: CollectionsCacheService,
    private readonly cacheInvalidation: CacheInvalidationService,
  ) {}

  async getUserCollections({
    userId,
    cursor = null,
    limit = 20,
  }: {
    userId: string;
    cursor?: string | null;
    limit?: number;
  }) {
    // Use cache for user collections
    return await this.collectionsCache.getUserCollections(userId, async () => {
      const query: any = { owner: userId };

      if (cursor) {
        Object.assign(query, buildCursorQuery(cursor, "createdAt", -1));
      }

      const collections = await this.collectionModel
        .find(query)
        .select("name isPrivate isDefault createdAt")
        .sort({ isDefault: -1, createdAt: -1 })
        .limit(limit + 1)
        .lean();

      const { data, pagination } = processPaginatedResults(collections, limit, [
        "createdAt",
      ]);

      return {
        collections: data,
        pagination,
      };
    });
  }

  async getCollectionDetails({
    collectionId,
    cursor = null,
    limit = 20,
  }: {
    collectionId: string;
    cursor?: string | null;
    limit?: number;
  }) {
    // Use cache for collection items
    return await this.collectionsCache.getCollectionItems(collectionId, async () => {
      const query: any = { collectionId };

      if (cursor) {
        Object.assign(query, buildCursorQuery(cursor, "addedAt", -1));
      }

      const items = await this.collectionItemModel
        .find(query)
        .sort({ addedAt: -1 })
        .limit(limit + 1)
        .populate({
          path: "quoteId",
          select: "text author category reactions likes saves requotes createdAt",
        })
        .lean();

      const { data, pagination } = processPaginatedResults(items, limit, [
        "addedAt",
      ]);

      return {
        items: data.map((i: any) => i.quoteId),
        pagination,
      };
    });
  }

  async toggleSave(
    userId: string,
    quoteId: string,
    collectionId: string | null = null,
  ) {
    let targetCollectionId = collectionId;

    if (!targetCollectionId) {
      let defaultCollection = await this.collectionModel.findOne({
        owner: userId,
        isDefault: true,
      });
      if (!defaultCollection) {
        defaultCollection = await this.collectionModel.create({
          owner: userId,
          name: "Saved",
          isPrivate: true,
          isDefault: true,
        });
      }
      targetCollectionId = defaultCollection._id.toString();
    } else {
      const isOwner = await this.collectionModel.exists({
        _id: targetCollectionId,
        owner: userId,
      });
      if (!isOwner) throw new UnauthorizedException("Unauthorized");
    }

    const existing = await this.collectionItemModel.findOne({
      collectionId: targetCollectionId,
      quoteId,
    });

    if (existing) {
      await this.collectionItemModel.deleteOne({ _id: existing._id });
      await this.quoteModel.findByIdAndUpdate(quoteId, { $inc: { saves: -1 } });
      
      // Invalidate cache
      this.cacheInvalidation.emitCollectionUpdated(targetCollectionId, userId);
      
      return { saved: false };
    }

    await this.collectionItemModel.create({
      collectionId: targetCollectionId,
      quoteId,
    });
    await this.quoteModel.findByIdAndUpdate(quoteId, { $inc: { saves: 1 } });

    // Invalidate cache
    this.cacheInvalidation.emitCollectionUpdated(targetCollectionId, userId);

    return { saved: true };
  }
}

