import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';

import Quote from '../../models/quote.model';
import Follow from '../../models/follow.model';
import Block from '../../models/block.model';
import UserContentPreference from '../../models/userContentPreference.model';
import {
  buildCursorQuery,
  buildCompoundCursorQuery,
  processPaginatedResults,
} from '../../shared/utils/cursor.util';
import { QuoteCacheService } from '../../infrastructure/cache/quote.cache';

@Injectable()
export class FeedsService {
  constructor(
    @InjectModel(Quote.name) private quoteModel: Model<any>,
    @InjectModel(Follow.name) private followModel: Model<any>,
    @InjectModel(Block.name) private blockModel: Model<any>,
    @InjectModel(UserContentPreference.name) private preferenceModel: Model<any>,
    private readonly quoteCache: QuoteCacheService,
  ) {}

  async getGlobalFeed({ userId, cursor = null, limit = 10 }: { userId?: string; cursor?: string | null; limit?: number }) {
    // Use cache for global feed (simple version without user-specific blocking for now)
    const page = this.extractPageFromCursor(cursor);
    
    return await this.quoteCache.getGlobalFeed(page, async () => {
      const query: any = { isHiddenBySystem: { $ne: true } };

      if (userId) {
        const blocks = await this.blockModel.find({
          $or: [{ blocker: userId }, { blocked: userId }],
        }).lean();

        const blockedUserIds = blocks.map((b) =>
          b.blocker.toString() === userId.toString() ? b.blocked : b.blocker,
        );

        const preferences = await this.preferenceModel.find({ userId }).lean();

        const excludedQuoteIds = preferences
          .filter((p) => p.type === 'QUOTE')
          .map((p) => p.targetId);
        const excludedAuthors = preferences
          .filter((p) => p.type === 'AUTHOR')
          .map((p) => p.targetId);
        const excludedTags = preferences
          .filter((p) => p.type === 'TAG')
          .map((p) => p.targetId);

        const finalExcludedAuthors = [
          ...new Set([...blockedUserIds, ...excludedAuthors]),
        ];

        query._id = { $nin: excludedQuoteIds };
        query.authorId = { $nin: finalExcludedAuthors };
        query.tags = { $nin: excludedTags };
      }

      if (cursor) {
        Object.assign(query, buildCursorQuery(cursor, 'createdAt', -1));
      }

      const quotes = await this.quoteModel
        .find(query)
        .sort({ createdAt: -1 })
        .limit(limit + 1)
        .lean();

      const { data, pagination } = processPaginatedResults(quotes, limit, [
        'createdAt',
      ]);

      return {
        quotes: data,
        pagination,
      };
    });
  }

  private extractPageFromCursor(cursor: string | null): number {
    if (!cursor) return 1;
    try {
      const decoded = JSON.parse(Buffer.from(cursor, 'base64').toString());
      return decoded.page || 1;
    } catch {
      return 1;
    }
  }

  async getUserQuotes({
    targetUserId,
    viewerId = null,
    cursor = null,
    limit = 10,
  }: {
    targetUserId: string;
    viewerId?: string | null;
    cursor?: string | null;
    limit?: number;
  }) {
    const query = {
      creator: targetUserId,
      isHiddenBySystem: { $ne: true },
    };

    if (viewerId) {
      const isBlocked = await this.blockModel.findOne({
        $or: [
          { blocker: viewerId, blocked: targetUserId },
          { blocker: targetUserId, blocked: viewerId },
        ],
      }).lean();

      if (isBlocked) {
        return {
          quotes: [],
          pagination: { nextCursor: null, hasMore: false },
          isBlocked: true,
        };
      }
    }

    if (cursor) {
      Object.assign(query, buildCursorQuery(cursor, 'createdAt', -1));
    }

    const quotes = await this.quoteModel
      .find(query)
      .sort({ createdAt: -1 })
      .limit(limit + 1)
      .lean();

    const { data, pagination } = processPaginatedResults(quotes, limit, [
      'createdAt',
    ]);

    return {
      quotes: data,
      pagination,
    };
  }

  async getFollowingFeed({ userId, cursor = null, limit = 10 }: { userId: string; cursor?: string | null; limit?: number }) {
    const follows = await this.followModel.find({ follower: userId })
      .select('following')
      .lean();

    let followedUserIds = follows.map((f) => f.following);

    if (!followedUserIds.length) {
      return { quotes: [], pagination: { nextCursor: null, hasMore: false } };
    }

    const blocks = await this.blockModel.find({
      $or: [{ blocker: userId }, { blocked: userId }],
    }).lean();

    const blockedIds = blocks.map((b) =>
      b.blocker.toString() === userId.toString()
        ? b.blocked.toString()
        : b.blocker.toString(),
    );

    followedUserIds = followedUserIds.filter(
      (id) => !blockedIds.includes(id.toString()),
    );

    const preferences = await this.preferenceModel.find({ userId }).lean();

    const excludedQuoteIds = preferences
      .filter((p) => p.type === 'QUOTE')
      .map((p) => p.targetId);
    const excludedTags = preferences
      .filter((p) => p.type === 'TAG')
      .map((p) => p.targetId);

    const query = {
      author: { $in: followedUserIds },
      _id: { $nin: excludedQuoteIds },
      tags: { $nin: excludedTags },
      isHiddenBySystem: { $ne: true },
    };

    if (cursor) {
      Object.assign(
        query,
        buildCompoundCursorQuery(cursor, ['createdAt', '_id'], [-1, -1]),
      );
    }

    const quotes = await this.quoteModel
      .find(query)
      .sort({ createdAt: -1, _id: -1 })
      .limit(limit + 1)
      .lean();

    const { data, pagination } = processPaginatedResults(quotes, limit, [
      'createdAt',
      '_id',
    ]);

    return {
      quotes: data,
      pagination,
    };
  }

  async getDiscoverFeed({ userId, cursor = null, limit = 20 }: { userId?: string; cursor?: string | null; limit?: number }) {
    // Use cache for discover feed
    const page = this.extractPageFromCursor(cursor);
    
    return await this.quoteCache.getDiscoverFeed(page, async () => {
      const query: any = {
        creator: { $ne: userId },
        isHiddenBySystem: { $ne: true },
      };

      if (userId) {
        const follows = await this.followModel.find({ follower: userId })
          .select('following')
          .lean();
        const followedUserIds = follows.map((f) => f.following);

        const blocks = await this.blockModel.find({
          $or: [{ blocker: userId }, { blocked: userId }],
        }).lean();
        const blockedIds = blocks.map((b) =>
          b.blocker.toString() === userId.toString() ? b.blocked : b.blocker,
        );

        const preferences = await this.preferenceModel.find({ userId }).lean();

        const excludedQuoteIds = preferences
          .filter((p) => p.type === 'QUOTE')
          .map((p) => p.targetId);
        const excludedAuthors = preferences
          .filter((p) => p.type === 'AUTHOR')
          .map((p) => p.targetId);
        const excludedTags = preferences
          .filter((p) => p.type === 'TAG')
          .map((p) => p.targetId);

        const totalExcludedAuthors = [
          ...new Set([
            ...followedUserIds.map((id) => id.toString()),
            ...blockedIds.map((id) => id.toString()),
            ...excludedAuthors.map((id) => id.toString()),
            userId.toString(),
          ]),
        ];

        query.creator = { $nin: totalExcludedAuthors };
        query._id = { $nin: excludedQuoteIds };
        query.tags = { $nin: excludedTags };
      }

      if (cursor) {
        Object.assign(query, buildCursorQuery(cursor, 'createdAt', -1));
      }

      const quotes = await this.quoteModel
        .find(query)
        .sort({ createdAt: -1 })
        .limit(limit + 1)
        .lean();

      const { data, pagination } = processPaginatedResults(quotes, limit, [
        'createdAt',
      ]);

      return {
        quotes: data,
        pagination,
      };
    });
  }
}

import Notification from "../../models/notification.model";
import { NOTIFICATION_CONFIG } from "./notification.constants";
import { getIO } from "./notification.socket";
import {
  buildCursorQuery,
  processPaginatedResults,
} from "../../shared/utils/cursor.util";

declare global {
  var userSocketMap: Map<string, Set<string>> | undefined;
}

interface CreateNotificationData {
  recipient: string;
  sender: string;
  type: string;
  message: string;
  referenceId?: string;
  referenceType?: string;
  metadata?: any;
}

interface GetNotificationsOptions {
  cursor?: string | null;
  limit?: number;
  unreadOnly?: boolean;
}

const createNotification = async ({
  recipient,
  sender,
  type,
  message,
  referenceId,
  referenceType,
  metadata = {},
}: CreateNotificationData) => {
  try {
    const notification = await Notification.create({
      recipient,
      sender,
      type,
      message,
      referenceId,
      referenceType,
      metadata,
    });

    await sendRealtimeNotification(recipient, notification);

    return notification;
  } catch (error) {
    console.error("Error creating notification:", error);
    throw error;
  }
};

const sendRealtimeNotification = async (
  recipientId: string,
  notification: any,
) => {
  try {
    const io = getIO();
    if (!io) {
      console.warn("Socket.IO not initialized, skipping real-time delivery");
      return false;
    }

    const userSocketMap = getUserSocketMap();
    const socketIds = userSocketMap.get(recipientId);

    if (socketIds && socketIds.size > 0) {
      socketIds.forEach((socketId) => {
        io.to(socketId).emit("notification:new", notification);
      });
      return true;
    }

    return false;
  } catch (error) {
    console.error("Error sending real-time notification:", error);
    return false;
  }
};

const getUserSocketMap = (): Map<string, Set<string>> => {
  if (!global.userSocketMap) {
    global.userSocketMap = new Map();
  }
  return global.userSocketMap;
};

const registerUserSocket = (userId: string, socketId: string) => {
  const userSocketMap = getUserSocketMap();
  if (!userSocketMap.has(userId)) {
    userSocketMap.set(userId, new Set());
  }
  userSocketMap.get(userId)!.add(socketId);
};

const unregisterUserSocket = (userId: string, socketId: string) => {
  const userSocketMap = getUserSocketMap();
  if (userSocketMap.has(userId)) {
    userSocketMap.get(userId)!.delete(socketId);
    if (userSocketMap.get(userId)!.size === 0) {
      userSocketMap.delete(userId);
    }
  }
};

const isUserOnline = (userId: string): boolean => {
  const userSocketMap = getUserSocketMap();
  return userSocketMap.has(userId) && userSocketMap.get(userId)!.size > 0;
};

const getNotifications = async (
  userId: string,
  {
    cursor = null,
    limit = NOTIFICATION_CONFIG.DEFAULT_PAGE_SIZE,
    unreadOnly = false,
  }: GetNotificationsOptions = {},
) => {
  try {
    const sanitizedLimit = Math.min(limit, NOTIFICATION_CONFIG.MAX_PAGE_SIZE);

    const query: any = {
      recipient: userId,
      isDeleted: false,
    };

    if (unreadOnly) {
      query.isRead = false;
    }

    if (cursor) {
      Object.assign(query, buildCursorQuery(cursor, "createdAt", -1));
    }

    const notifications = await Notification.find(query)
      .populate("sender", "username name avatar")
      .sort({ createdAt: -1 })
      .limit(sanitizedLimit + 1)
      .lean();

    const { data, pagination } = processPaginatedResults(
      notifications,
      sanitizedLimit,
      ["createdAt"],
    );

    return {
      notifications: data,
      pagination,
    };
  } catch (error) {
    console.error("Error getting notifications:", error);
    throw error;
  }
};

const markAsRead = async (notificationId: string, userId: string) => {
  try {
    const notification = await Notification.findOne({
      _id: notificationId,
      recipient: userId,
      isDeleted: false,
    });

    if (!notification) {
      throw new Error("Notification not found");
    }

    if (notification.isRead) {
      return notification;
    }

    notification.isRead = true;
    await notification.save();

    await emitUnreadCount(userId);

    return notification;
  } catch (error) {
    console.error("Error marking notification as read:", error);
    throw error;
  }
};

const markAllAsRead = async (userId: string) => {
  try {
    const result = await Notification.updateMany(
      {
        recipient: userId,
        isRead: false,
        isDeleted: false,
      },
      { isRead: true },
    );

    await emitUnreadCount(userId);

    return {
      modifiedCount: result.modifiedCount,
    };
  } catch (error) {
    console.error("Error marking all notifications as read:", error);
    throw error;
  }
};

const getUnreadCount = async (userId: string): Promise<number> => {
  try {
    const count = await Notification.countDocuments({
      recipient: userId,
      isRead: false,
      isDeleted: false,
    });
    return count;
  } catch (error) {
    console.error("Error getting unread count:", error);
    throw error;
  }
};

const emitUnreadCount = async (userId: string) => {
  try {
    const io = getIO();
    if (!io) {
      return;
    }

    const unreadCount = await getUnreadCount(userId);
    const userSocketMap = getUserSocketMap();
    const socketIds = userSocketMap.get(userId);

    if (socketIds && socketIds.size > 0) {
      socketIds.forEach((socketId) => {
        io.to(socketId).emit("notification:count", { unreadCount });
      });
    }
  } catch (error) {
    console.error("Error emitting unread count:", error);
  }
};

const deleteNotification = async (notificationId: string, userId: string) => {
  try {
    const notification = await Notification.findOne({
      _id: notificationId,
      recipient: userId,
    });

    if (!notification) {
      throw new Error("Notification not found");
    }

    notification.isDeleted = true;
    await notification.save();

    return notification;
  } catch (error) {
    console.error("Error deleting notification:", error);
    throw error;
  }
};

const notificationService = {
  createNotification,
  sendRealtimeNotification,
  getUserSocketMap,
  registerUserSocket,
  unregisterUserSocket,
  isUserOnline,
  getNotifications,
  markAsRead,
  markAllAsRead,
  getUnreadCount,
  emitUnreadCount,
  deleteNotification,
};

export default notificationService;

import jwt from "jsonwebtoken";
import { Server, Socket } from "socket.io";
import notificationService from "./notification.service";
import { SOCKET_EVENTS } from "./notification.constants";

let io: Server | null = null;

const initializeSocket = (server: any): Server => {
  if (io) {
    console.warn("Socket.IO already initialized");
    return io;
  }

  io = new Server(server, {
    cors: {
      origin: process.env.SOCKET_CORS_ORIGIN || "http://localhost:3001",
      methods: ["GET", "POST"],
    },
    transports: ["websocket", "polling"],
  });

  io.use((socket: Socket & { userId?: string; username?: string }, next: any) => {
    const token = socket.handshake.auth.token;

    if (!token) {
      return next(new Error("Authentication error: Token missing"));
    }

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET || "") as any;
      socket.userId = decoded.userId;
      socket.username = decoded.username;
      next();
    } catch {
      next(new Error("Authentication error: Invalid token"));
    }
  });

  io.on("connection", (socket: Socket & { userId?: string; username?: string }) => {
    console.log(`User connected: ${socket.userId}, Socket ID: ${socket.id}`);

    notificationService.registerUserSocket(socket.userId, socket.id);

    socket.emit(SOCKET_EVENTS.USER_REGISTERED, {
      userId: socket.userId,
      socketId: socket.id,
    });

    socket.on(SOCKET_EVENTS.REGISTER_USER, (data: any) => {
      if (data.userId === socket.userId) {
        notificationService.registerUserSocket(socket.userId, socket.id);
      }
    });

    socket.on(SOCKET_EVENTS.NOTIFICATION_READ, async (data: any) => {
      try {
        const { notificationId } = data;
        await notificationService.markAsRead(notificationId, socket.userId);
      } catch (error: any) {
        console.error("Error handling notification:read:", error);
        socket.emit("error", {
          message: "Failed to mark notification as read",
        });
      }
    });

    socket.on("disconnect", (reason: string) => {
      console.log(
        `User disconnected: ${socket.userId}, Socket ID: ${socket.id}, Reason: ${reason}`,
      );
      notificationService.unregisterUserSocket(socket.userId, socket.id);
    });

    socket.on("error", (error: Error) => {
      console.error(`Socket error for user ${socket.userId}:`, error);
    });
  });

  console.log("Socket.IO server initialized");
  return io;
};

const getIO = (): Server | null => {
  return io;
};

export { initializeSocket, getIO };

