import { Controller, UseInterceptors, Get, Post, Patch, Delete, Param, Query, UseGuards, Request, Body } from '@nestjs/common';
import { QuotesService } from './quotes.service';
import { ResponseInterceptor } from '../../shared/interceptors/response.interceptor';
import { AuthGuard } from '../../shared/guards/auth.guard';

@Controller('quote')
@UseInterceptors(ResponseInterceptor)
@UseGuards(AuthGuard)
export class QuotesController {
  constructor(private quotesService: QuotesService) {}

  @Post()
  async createQuote(@Request() req: any, @Body() body: any) {
    const {
      text,
      author,
      category,
      hashtags,
      taggedUsers,
      isRequote = false,
      parentQuoteId = null,
      isHiddenBySystem = false,
    } = body;

    if (!isRequote && !text) {
      throw new Error('Quote text is required');
    }

    if (isRequote && !parentQuoteId) {
      throw new Error('Parent quote ID is required for requote');
    }

    const newQuote = await this.quotesService.createQuote({
      text: text || '',
      author,
      category: category || '',
      hashtags: hashtags || [],
      taggedUsers: taggedUsers || [],
      creator: req.user.userId,
      isRequote,
      parentQuoteId,
      isHiddenBySystem,
    });

    if (!newQuote) {
      throw new Error('Failed to create quote');
    }

    return {
      success: true,
      statusCode: 201,
      message: isRequote ? 'Requote created successfully' : 'Quote created successfully',
      data: newQuote,
    };
  }

  @Get(':id')
  async getQuoteById(@Param('id') quoteId: string) {
    const quote = await this.quotesService.getQuoteById(quoteId);
    if (!quote) {
      throw new Error('Quote not found');
    }
    return {
      success: true,
      statusCode: 200,
      message: 'Quote retrieved successfully',
      data: quote,
    };
  }

  @Get()
  async getAllQuotes() {
    const quotes = await this.quotesService.getAllQuotes();
    return {
      success: true,
      statusCode: 200,
      message: 'Quotes retrieved successfully',
      data: quotes,
    };
  }

  @Patch(':id')
  async updateQuote(@Param('id') quoteId: string, @Body() updateData: any) {
    const updatedQuote = await this.quotesService.updateQuote(quoteId, updateData);
    if (!updatedQuote) {
      throw new Error('Quote not found or update failed');
    }
    return {
      success: true,
      statusCode: 200,
      message: 'Quote updated successfully',
      data: updatedQuote,
    };
  }

  @Delete(':id')
  async deleteQuote(@Param('id') quoteId: string) {
    const deletedQuote = await this.quotesService.deleteQuote(quoteId);
    if (!deletedQuote) {
      throw new Error('Quote not found or deletion failed');
    }
    return {
      success: true,
      statusCode: 200,
      message: 'Quote deleted successfully',
      data: deletedQuote,
    };
  }

  @Get('me')
  async getQuotesByUser(@Request() req: any, @Query('cursor') cursor?: string, @Query('limit') limit?: string) {
    const userId = req.user.id;
    const userQuotes = await this.quotesService.getQuotesByUser({
      userId,
      cursor: cursor || null,
      limit: limit ? Number.parseInt(limit, 10) : 20,
    });
    if (!userQuotes) {
      throw new Error('No quotes found for this user');
    }
    return {
      success: true,
      statusCode: 200,
      message: 'User quotes retrieved successfully',
      data: userQuotes,
    };
  }
}

import { Injectable, BadRequestException, NotFoundException } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';

import Quote, { IQuote } from '../../models/quote.model';
import User, { IUser } from '../../models/user.model';
import { addImageGenerationJob } from '../../shared/queues/imageGeneration.queue';
import { NotificationsService } from '../notifications/notifications.service';
import { NOTIFICATION_TYPES, REFERENCE_TYPES } from '../notifications/notification.constants';
import { buildCursorQuery, processPaginatedResults } from '../../shared/utils/cursor.util';
import { QuoteCacheService } from '../../infrastructure/cache/quote.cache';
import { CacheInvalidationService } from '../../infrastructure/cache/cache-invalidation.service';

const IMAGE_GENERATION_ENABLED = process.env.IMAGE_GENERATION_ENABLED === 'true';
const NOTIFICATIONS_ENABLED = process.env.NOTIFICATIONS_ENABLED === 'true';

@Injectable()
export class QuotesService {
  constructor(
    @InjectModel(Quote.name) private quoteModel: Model<IQuote>,
    @InjectModel(User.name) private userModel: Model<IUser>,
    private notificationsService: NotificationsService,
    private readonly quoteCache: QuoteCacheService,
    private readonly cacheInvalidation: CacheInvalidationService,
  ) {}

  async createQuote({
    text,
    author,
    category,
    hashtags = [],
    taggedUsers = [],
    creator,
    isRequote = false,
    parentQuoteId = null,
    isHiddenBySystem = false,
  }: {
    text: string;
    author?: string;
    category?: string;
    hashtags?: string[];
    taggedUsers?: string[];
    creator: string;
    isRequote?: boolean;
    parentQuoteId?: string;
    isHiddenBySystem?: boolean;
  }) {
    const session = await this.quoteModel.startSession();
    session.startTransaction();

    try {
      if (isRequote) {
        if (!parentQuoteId) {
          throw new BadRequestException('parentQuoteId is required for requote');
        }

        const parentQuote = await this.quoteModel.findOne({
          _id: parentQuoteId,
          isHiddenBySystem: false,
        }).session(session);

        if (!parentQuote) {
          throw new NotFoundException('Parent quote not found or hidden');
        }

        const alreadyRequoted = await this.quoteModel.exists({
          creator,
          parentQuoteId,
        }).session(session);

        if (alreadyRequoted) {
          throw new BadRequestException('Already requoted');
        }
      }

      const newQuote = await this.quoteModel.create(
        [
          {
            text,
            author: author || 'Anonymous',
            category: category || '',
            hashtags: hashtags || [],
            taggedUsers,
            creator,
            isRequote,
            parentQuoteId,
            isHiddenBySystem,
          },
        ],
        { session }
      );

      if (isRequote) {
        await this.quoteModel.updateOne({ _id: parentQuoteId }, { $inc: { requotes: 1 } }, { session });

        if (NOTIFICATIONS_ENABLED) {
          void process.nextTick(async () => {
            try {
              const parentQuote = await this.quoteModel.findById(parentQuoteId)
                .select('creator text author')
                .lean();
              const requoter = await this.userModel.findById(creator).lean();

              if (parentQuote && requoter && parentQuote.creator.toString() !== creator) {
                await this.notificationsService.createNotification({
                  recipient: parentQuote.creator.toString(),
                  sender: creator,
                  type: NOTIFICATION_TYPES.REQUOTE_QUOTE,
                  message: `${requoter.username || 'Someone'} requoted your quote`,
                  referenceId: newQuote[0]._id.toString(),
                  referenceType: REFERENCE_TYPES.QUOTE,
                  metadata: {
                    originalQuoteId: parentQuoteId,
                    originalQuoteText: parentQuote.text,
                    originalQuoteAuthor: parentQuote.author,
                    senderName: requoter.username,
                  },
                });
              }
            } catch (error) {
              console.error('Failed to create requote notification:', error);
            }
          });
        }
      }

      void session.commitTransaction();
      void session.endSession();

      const savedQuote = newQuote[0];
      
      // Warm up cache for new quote
      await this.quoteCache.warmUpQuoteCache(savedQuote);
      
      // Invalidate user quotes cache and feeds
      this.cacheInvalidation.emitQuoteCreated(savedQuote._id.toString(), creator);
      
      if (IMAGE_GENERATION_ENABLED) {
        void process.nextTick(() => {
          addImageGenerationJob({ quoteId: savedQuote._id.toString() }).catch(err => {
            console.error('Failed to enqueue image generation job:', err);
          });
        });
      }
      return savedQuote;
    } catch (error) {
      void session.abortTransaction();
      void session.endSession();
      throw error;
    }
  }

  async getQuoteById(id: string) {
    return await this.quoteCache.getQuote(id, async () => {
      const quote = await this.quoteModel.findById(id);
      if (!quote) {
        throw new NotFoundException('Quote not found');
      }
      return quote;
    });
  }

  async getAllQuotes() {
    return await this.quoteModel.find();
  }

  async updateQuote(id: string, updateData: any) {
    const updatedQuote = await this.quoteModel.findByIdAndUpdate(id, updateData, { new: true });
    if (updatedQuote) {
      // Invalidate quote cache
      this.cacheInvalidation.emitQuoteUpdated(id);
      // Warm up cache with updated quote
      await this.quoteCache.warmUpQuoteCache(updatedQuote);
    }
    return updatedQuote;
  }

  async deleteQuote(id: string) {
    const quote = await this.quoteModel.findById(id);
    if (quote) {
      await this.quoteModel.findByIdAndDelete(id);
      // Invalidate quote cache
      this.cacheInvalidation.emitQuoteDeleted(id, quote.creator?.toString() || '');
      return quote;
    }
    return null;
  }

  async getQuotesByUser({ userId, cursor = null, limit = 20 }: { userId: string; cursor?: string | null; limit?: number }) {
    const query = { creator: userId };

    if (cursor) {
      Object.assign(query, buildCursorQuery(cursor, 'createdAt', -1));
    }

    const quotes = await this.quoteModel.find(query)
      .sort({ createdAt: -1 })
      .limit(limit + 1)
      .lean();

    const { data, pagination } = processPaginatedResults(quotes, limit, ['createdAt']);

    return {
      quotes: data,
      pagination,
    };
  }

  async likeQuote(quoteId: string, _userId: string) {
    const quote = await this.quoteModel.findById(quoteId);
    if (!quote) {
      return null;
    }
    await this.quoteModel.findByIdAndUpdate(quoteId, { $inc: { likes: 1 } });
    const updatedQuote = await this.quoteModel.findById(quoteId);
    return { likeCount: updatedQuote?.likes || 0 };
  }
}

import mongoose from 'mongoose';
import Reaction from '../../models/reaction.model';
import Quote from '../../models/quote.model';
import Follow from '../../models/follow.model';
import { redis, RedisKeys } from '../../shared/utils/redis.utils';
import { atomicUpdateCache, getReactionBreakdown } from '../../infrastructure/cache/reaction.cache';
import { producer } from '../../infrastructure/kafka/config/kafka.config';
import { enqueueNotificationJob } from '../../shared/queues/quoteNotifications.queue';
import { buildCursorQuery, processPaginatedResults } from '../../shared/utils/cursor.util';

const NOTIFICATIONS_ENABLED = process.env.NOTIFICATIONS_ENABLED === 'true';

const reactionService = {
  toggleReaction: async ({ userId, quoteId, type }) => {
    // 1. RATE LIMITING (Using our new custom command)
    const allowed = await (redis as any).slidingWindowRateLimit(
      RedisKeys.rateLimitBurst(userId),
      RedisKeys.rateLimitSustain(userId),
      Date.now(),
      10000, // burst window (10s)
      5, // burst limit
      3600000, // sustained window (1hr)
      20 // sustained limit
    );
    if (!allowed) throw new Error('Too many requests');

    // 2. Determine Action
    const stateKey = RedisKeys.reactionState(userId, quoteId);
    const existingType = await redis.get(stateKey);

    let action,
      oldType = null;

    if (!existingType) {
      action = 'added';
    } else if (existingType === type) {
      action = 'removed';
    } else {
      action = 'updated';
      oldType = existingType;
    }

    // 3. UPDATE REDIS (Fast Path)
    const delta = action === 'added' ? 1 : action === 'removed' ? -1 : 0;

    // Execute state update and count update concurrently
    const updatePromises = [atomicUpdateCache(quoteId, type, delta, oldType)];

    // CRITICAL FIX: Ensure the user's individual state is eagerly updated in Redis
    if (action === 'removed') {
      updatePromises.push(redis.del(stateKey));
    } else {
      // Set state with a TTL (e.g., 30 days) to prevent infinite memory growth
      updatePromises.push(redis.setex(stateKey, 2592000, type));
    }
    await Promise.all(updatePromises);

    // 4. KAFKA PRODUCER (Persistent Path)
    // Fire and forget, or handle errors so Kafka downtime doesn't break the UI
    producer
      .send({
        topic: 'reaction-events',
        messages: [
          {
            key: quoteId,
            value: JSON.stringify({
              eventId: `${userId}:${quoteId}`,
              userId,
              quoteId,
              type,
              action,
              oldType,
              timestamp: Date.now(),
            }),
          },
        ],
      })
      .catch(err => {
        console.error('Failed to publish reaction to Kafka:', err);
        // Optional: Push to a dead-letter queue or local retry mechanism here
      });

    // Enqueue a notification for the quote owner when someone likes their quote
    if (action === 'added' && type === 'like') {
      void process.nextTick(async () => {
        try {
          const quote = await Quote.findById(quoteId).select('creator').lean();
          const recipientId = quote?.creator?.toString();
          if (recipientId && recipientId !== userId && NOTIFICATIONS_ENABLED) {
            enqueueNotificationJob({
              type: 'quote-like',
              recipientId,
              actorId: userId,
              quoteId,
            }).catch(err => console.error('Failed to enqueue quote-like notification:', err));
          }
        } catch (e) {
          console.error('Failed to lookup quote for notification:', e);
        }
      });
    }

    // 5. IMMEDIATE RESPONSE
    return { success: true, action, type };
  },

  getQuoteReactions: async ({ quoteId, viewerId, type, cursor, limit = 10 }) => {
    // 1. GET COUNTS
    const { breakdown, total } = await getReactionBreakdown(quoteId);

    // 2. FIRST-PAGE CACHING
    const firstPageKey = RedisKeys.firstPageReactions(quoteId, viewerId || 'guest');
    if (!cursor && !type) {
      try {
        const cached = await redis.get(firstPageKey);
        if (cached) return JSON.parse(cached);
      } catch (err) {
        console.warn('Failed to fetch first-page cache:', err.message);
      }
    }

    // 3. SOCIAL PRIORITY QUERY
    let followingIds = [];
    if (viewerId) {
      const followingKey = RedisKeys.userFollowing(viewerId);
      try {
        followingIds = await redis.smembers(followingKey);
      } catch (err) {
        console.warn('Redis smembers failed, falling back to DB:', err.message);
      }

      if (followingIds.length === 0) {
        followingIds = await Follow.find({ followerId: viewerId }).distinct('followingId');

        if (followingIds.length > 0) {
          try {
            // Fire and forget the read-repair
            void redis
              .pipeline()
              .sadd(followingKey, ...followingIds.map(id => id.toString()))
              .expire(followingKey, 86400)
              .exec();
          } catch (err) {
            console.error('Failed to repair following cache:', err.message);
          }
        }
      }
    }

    const query: any = { quoteId: new mongoose.Types.ObjectId(quoteId) };
    if (type) query.type = type;
    if (cursor) {
      Object.assign(query, buildCursorQuery(cursor, 'createdAt', -1));
    }

    // 4. THE MONGO AGGREGATION
    const reactions = await Reaction.aggregate([
      { $match: query },
      {
        $addFields: {
          isFriend: {
            $in: ['$userId', followingIds.map(id => new mongoose.Types.ObjectId(id))],
          },
        },
      },
      { $sort: { isFriend: -1, createdAt: -1 } },
      { $limit: limit + 1 },
      {
        $lookup: {
          from: 'users',
          localField: 'userId',
          foreignField: '_id',
          as: 'user',
        },
      },
      { $unwind: '$user' },
      {
        $project: {
          type: 1,
          createdAt: 1,
          isFriend: 1,
          user: { _id: 1, name: 1, username: 1, avatar: 1 },
        },
      },
    ]);

    // 5. PAGINATION & CACHE FILL
    const { data, pagination } = processPaginatedResults(reactions, limit, ['createdAt']);

    const result = {
      total,
      breakdown,
      users: data,
      pagination,
    };

    if (!cursor && !type) {
      redis.setex(firstPageKey, 30, JSON.stringify(result)).catch(err => {
        console.warn('Failed to set first-page cache:', err.message);
      });
    }

    return result;
  },
};

export default reactionService;

import {
  Injectable,
  BadRequestException,
  ConflictException,
} from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";

import { IUserBlock } from "../../models/block.model";
import { IReport } from "../../models/report.model";
import { IUser } from "../../models/user.model";
import { IQuote } from "../../models/quote.model";
import { IFollow } from "../../models/follow.model";
import { IReportStats } from "../../models/reportStats.model";

@Injectable()
export class SafetyService {
  constructor(
    @InjectModel("Block") private readonly blockModel: Model<IUserBlock>,
    @InjectModel("Report") private readonly reportModel: Model<IReport>,
    @InjectModel("User") private readonly userModel: Model<IUser>,
    @InjectModel("Quote") private readonly quoteModel: Model<IQuote>,
    @InjectModel("Follow") private readonly followModel: Model<IFollow>,
    @InjectModel("ReportStats")
    private readonly reportStatsModel: Model<IReportStats>,
  ) {}

  async toggleBlockUser(blockerId: string, blockedId: string) {
    if (blockerId.toString() === blockedId.toString()) {
      throw new BadRequestException("Users cannot block themselves");
    }

    const existingBlock = await this.blockModel.findOne({
      blocker: blockerId,
      blocked: blockedId,
    });

    if (existingBlock) {
      await this.blockModel.deleteOne({ _id: existingBlock._id });
      return { blocked: false };
    } else {
      const session = await this.blockModel.startSession();
      session.startTransaction();
      try {
        await this.blockModel.create(
          [{ blocker: blockerId, blocked: blockedId }],
          {
            session,
          },
        );

        await this.followModel.deleteMany(
          {
            $or: [
              { follower: blockerId, following: blockedId },
              { follower: blockedId, following: blockerId },
            ],
          },
          { session },
        );

        await session.commitTransaction();
        return { blocked: true };
      } catch (error) {
        await session.abortTransaction();
        throw error;
      } finally {
        await session.endSession();
      }
    }
  }

  async report(
    reporterId: string,
    targetType: string,
    targetId: string,
    reason: string,
  ) {
    try {
      await this.reportModel.create({
        reporterId,
        targetType,
        targetId,
        reason,
      });

      const stats = await this.reportStatsModel.findOneAndUpdate(
        { targetId },
        {
          targetType,
          $inc: { totalReports: 1 },
          lastReportedAt: new Date(),
          status: "PENDING",
        },
        { upsert: true, new: true },
      );

      if (stats.totalReports >= 10) {
        await this.quoteModel.findByIdAndUpdate(targetId, {
          isHiddenBySystem: true,
        });
      }

      return stats;
    } catch (err: any) {
      if (err.code === 11000) throw new ConflictException("Already reported.");
      throw err;
    }
  }
}

import { Injectable } from "@nestjs/common";
import { InjectModel } from "@nestjs/mongoose";
import { Model } from "mongoose";
import mongoose from "mongoose";

import User, { IUser } from "../../models/user.model";
import Quote, { IQuote } from "../../models/quote.model";
import {
  decodeCursor,
  buildCursorQuery,
  processPaginatedResults,
} from "../../shared/utils/cursor.util";
import { SearchCacheService } from "../../infrastructure/cache/search.cache";
import { CacheInvalidationService } from "../../infrastructure/cache/cache-invalidation.service";

@Injectable()
export class SearchService {
  constructor(
    @InjectModel(User.name) private userModel: Model<IUser>,
    @InjectModel(Quote.name) private quoteModel: Model<IQuote>,
    private readonly searchCache: SearchCacheService,
    private readonly cacheInvalidation: CacheInvalidationService,
  ) {}

  async searchUsers({
    query,
    cursor = null,
    limit = 20,
  }: {
    query: string;
    cursor?: any;
    limit?: number;
  }) {
    if (!query || !query.trim()) {
      return {
        users: [],
        pagination: { nextCursor: null, hasMore: false },
      };
    }

    // Use cache for user search results
    return await this.searchCache.getUserSearchResults(query, async () => {
      const escaped = query.replace(/[*+?^${}()|[\]\\]/g, "\\$&");
      const exactRegex = new RegExp(`^${escaped}$`, "i");
      const prefixRegex = new RegExp(`^${escaped}`, "i");
      const containsRegex = new RegExp(escaped, "i");

      const pipeline: any[] = [
        {
          $match: {
            $or: [
              { username: containsRegex },
              { firstName: containsRegex },
              { lastName: containsRegex },
            ],
          },
        },
        {
          $addFields: {
            score: {
              $add: [
                {
                  $cond: [
                    { $regexMatch: { input: "$username", regex: exactRegex } },
                    100,
                    0,
                  ],
                },
                {
                  $cond: [
                    { $regexMatch: { input: "$username", regex: prefixRegex } },
                    60,
                    0,
                  ],
                },
                {
                  $cond: [
                    { $regexMatch: { input: "$firstName", regex: prefixRegex } },
                    40,
                    0,
                  ],
                },
                {
                  $cond: [
                    { $regexMatch: { input: "$lastName", regex: prefixRegex } },
                    40,
                    0,
                  ],
                },
                {
                  $cond: [
                    { $regexMatch: { input: "$username", regex: containsRegex } },
                    20,
                    0,
                  ],
                },
                {
                  $cond: [
                    {
                      $regexMatch: { input: "$firstName", regex: containsRegex },
                    },
                    10,
                    0,
                  ],
                },
                {
                  $cond: [
                    { $regexMatch: { input: "$lastName", regex: containsRegex } },
                    10,
                    0,
                  ],
                },
                { $cond: [{ $gt: ["$stats.followerCount", 1000] }, 15, 0] },
              ],
            },
          },
        },
        { $match: { score: { $gt: 0 } } },
      ];

      if (cursor) {
        const decoded = decodeCursor(cursor);
        pipeline.push({
          $match: {
            $or: [
              { score: { $lt: decoded.score } },
              {
                score: decoded.score,
                _id: { $gt: new mongoose.Types.ObjectId(String(decoded.id)) },
              },
            ],
          },
        });
      }

      pipeline.push(
        { $sort: { score: -1, _id: 1 } },
        { $limit: limit + 1 },
        { $project: { password: 0, __v: 0 } },
      );

      const users = await this.userModel.aggregate(pipeline);
      const { data, pagination } = processPaginatedResults(users, limit, [
        "score",
        "_id",
      ]);

      return {
        users: data,
        pagination,
      };
    });
  }

  async searchGlobal({ query, type = "all", limit = 20, cursor = {} as any }) {
    if (!query || !query.trim()) {
      return {
        results: { users: [], quotes: [], hashtags: [] },
        pagination: { nextCursor: null, hasMore: false },
      };
    }

    const escaped = query.replace(/[*+?^${}()|[\]\\]/g, "\\$&");
    const containsRegex = new RegExp(escaped, "i");
    const prefixRegex = new RegExp(`^${escaped}`, "i");

    const results: any = {
      users: [],
      quotes: [],
      hashtags: [],
    };

    const nextCursor: any = {};

    if (type === "all" || type === "users") {
      const userResult = await this.searchUsers({
        query,
        cursor: cursor.users || null,
        limit,
      });

      results.users = userResult.users;
      nextCursor.users = userResult.pagination.nextCursor;
    }

    if (type === "all" || type === "quotes") {
      // Use cache for quote search results
      results.quotes = await this.searchCache.getQuoteSearchResults(query, async () => {
        const quoteQuery: any = {
          isHiddenBySystem: false,
          $or: [{ text: containsRegex }, { hashtags: prefixRegex }],
        };

        if (cursor?.quotes) {
          Object.assign(
            quoteQuery,
            buildCursorQuery(cursor.quotes, "createdAt", -1),
          );
        }

        const quotes = await this.quoteModel
          .find(quoteQuery)
          .sort({ createdAt: -1 })
          .limit(limit + 1)
          .populate("creator", "username avatarUrl")
          .lean();

        const { data: quoteData, pagination: quotePagination } =
          processPaginatedResults(quotes, limit, ["createdAt"]);

        nextCursor.quotes = quotePagination.nextCursor;
        return quoteData;
      });
    }

    if (type === "all" || type === "hashtags") {
      // Use cache for hashtag search results
      results.hashtags = await this.searchCache.getHashtagSearchResults(query, async () => {
        const hashtags = await this.quoteModel.aggregate([
          { $match: { hashtags: prefixRegex } },
          { $unwind: "$hashtags" },
          { $match: { hashtags: prefixRegex } },
          { $group: { _id: "$hashtags", count: { $sum: 1 } } },
          { $sort: { count: -1 } },
          { $limit: Math.ceil(limit / 3) },
        ]);

        return hashtags.map((h: any) => ({
          tag: h._id,
          usageCount: h.count,
        }));
      });
    }

    return {
      results,
      pagination: {
        nextCursor,
        hasMore: Object.values(nextCursor).some(Boolean),
      },
    };
  }
}

import User from '../../models/user.model';
import Follow from '../../models/follow.model';
import Quote from '../../models/quote.model';
import { enqueueNotificationJob } from '../../shared/queues/quoteNotifications.queue';
import cloudinaryService from '../../infrastructure/media/cloudinary.service';
import { promises as fs } from 'fs';
import { buildCursorQuery, processPaginatedResults } from '../../shared/utils/cursor.util';

interface UpdateProfileData {
  firstName?: string;
  lastName?: string;
  bio?: string;
  avatarUrl?: string;
  username?: string;
}

interface AvatarFile {
  path: string;
}

const NOTIFICATIONS_ENABLED = process.env.NOTIFICATIONS_ENABLED === 'true';

const getUserByUsername = async (username: string) => {
  const user = await User.findOne({ username: username }).select('-password');
  return user;
};

const updateUserProfile = async (userId: string, updateData: UpdateProfileData) => {
  const allowedUpdates = ['firstName', 'lastName', 'bio', 'avatarUrl'];

  const filteredData: Partial<UpdateProfileData> = {};
  Object.keys(updateData).forEach(key => {
    if (allowedUpdates.includes(key)) {
      filteredData[key as keyof UpdateProfileData] = updateData[key as keyof UpdateProfileData];
    }
  });

  if (updateData.username) {
    const existing = await User.findOne({ username: updateData.username });
    if (existing && existing._id.toString() !== userId) {
      throw new Error('Username already taken');
    }
    filteredData.username = updateData.username;
  }

  const updatedUser = await User.findByIdAndUpdate(
    userId,
    { $set: filteredData },
    {
      new: true,
      runValidators: true,
      select: '-password',
    }
  ).lean();

  if (!updatedUser) {
    throw new Error('User not found');
  }

  return updatedUser;
};

const updateUserAvatar = async (userId: string, avatarFile: AvatarFile) => {
  let newAvatarUrl: string;
  const filePath = avatarFile.path;

  const user = (await User.findById(userId).select('avatar')) as any;
  if (!user) {
    throw new Error('User not found.');
  }

  try {
    newAvatarUrl = await cloudinaryService.uploadImage(filePath);

    if (user.avatar) {
      const oldPublicId = cloudinaryService.getPublicIdFromUrl(user.avatar);

      if (oldPublicId) {
        await cloudinaryService.deleteImage(oldPublicId);
      }
    }

    const updatedUser = await User.findByIdAndUpdate(
      userId,
      { $set: { avatar: newAvatarUrl } },
      { new: true, select: '-password' }
    );

    await fs.unlink(filePath);

    return updatedUser;
  } catch (error: unknown) {
    if (filePath) {
      await fs.unlink(filePath).catch(err => console.error('Cleanup error:', err));
    }
    throw error;
  }
};

const getSuggestedUsers = async ({
  userId = null,
  limit = 8,
}: {
  userId?: string | null;
  limit?: number;
}) => {
  if (!userId) {
    return await User.find({})
      .sort({ followersCount: -1, lastActiveAt: -1 })
      .limit(limit)
      .select('username firstName lastName avatarUrl bio stats isBanned');
  }

  const followed = await Follow.find({ follower: userId }).select('following').lean();

  const followedIds = followed.map(f => (f.following as any).toString());

  const suggestions = await Follow.aggregate([
    {
      $match: {
        follower: { $in: followedIds },
      },
    },
    {
      $group: {
        _id: '$following',
        mutualCount: { $sum: 1 },
      },
    },
    {
      $match: {
        _id: { $nin: [...followedIds, userId] },
      },
    },
    { $sort: { mutualCount: -1 } },
    { $limit: limit },
    {
      $lookup: {
        from: 'users',
        localField: '_id',
        foreignField: '_id',
        as: 'user',
      },
    },
    { $unwind: '$user' },
    {
      $project: {
        _id: '$user._id',
        username: '$user.username',
        firstName: '$user.firstName',
        lastName: '$user.lastName',
        avatar: '$user.avatar',
        mutualCount: 1,
      },
    },
  ]);

  return suggestions;
};

const toggleFollow = async (followerId: string, targetId: string) => {
  if (followerId === targetId) {
    throw new Error('You cannot follow yourself.');
  }

  const existingFollow = await Follow.findOne({
    follower: followerId,
    following: targetId,
  });

  if (existingFollow) {
    await Follow.deleteOne({ _id: existingFollow._id });

    await User.findByIdAndUpdate(followerId, {
      $inc: { 'stats.followingCount': -1 },
    });
    await User.findByIdAndUpdate(targetId, {
      $inc: { 'stats.followerCount': -1 },
    });

    return { followed: false, message: 'Unfollowed successfully' };
  } else {
    const newFollow = new Follow({
      follower: followerId,
      following: targetId,
    });
    await newFollow.save();

    await User.findByIdAndUpdate(followerId, {
      $inc: { 'stats.followingCount': 1 },
    });
    await User.findByIdAndUpdate(targetId, {
      $inc: { 'stats.followerCount': 1 },
    });

    if (NOTIFICATIONS_ENABLED) {
      void process.nextTick(() => {
        enqueueNotificationJob({
          type: 'user-follow',
          recipientId: targetId,
          actorId: followerId,
          subject: 'New follower on Qotes',
        }).catch((err: unknown) => {
          console.error('Failed to enqueue follow notification job:', err);
        });
      });
    }

    return { followed: true, message: 'Followed successfully' };
  }
};

const getUserRequotes = async ({
  userId,
  cursor = null,
  limit = 20,
}: {
  userId: string;
  cursor?: string | null;
  limit?: number;
}) => {
  const query: Record<string, unknown> = {
    creator: userId,
    isRequote: true,
    isHiddenBySystem: false,
  };

  if (cursor) {
    Object.assign(query, buildCursorQuery(cursor, '_id', -1));
  }

  const quotes = await Quote.find(query)
    .sort({ _id: -1 })
    .limit(limit + 1)
    .lean();

  const { data, pagination } = processPaginatedResults(quotes, limit, ['_id']);

  return {
    quotes: data,
    pagination,
  };
};

const getFollowers = async ({
  userId,
  currentUserId,
  cursor = null,
  limit = 20,
}: {
  userId: string;
  currentUserId?: string;
  cursor?: string | null;
  limit?: number;
}) => {
  const query: Record<string, unknown> = { following: userId };
  if (cursor) {
    Object.assign(query, buildCursorQuery(cursor, '_id', -1));
  }

  const follows = await Follow.find(query)
    .sort({ _id: -1 })
    .limit(limit + 1)
    .populate('follower', 'username firstName lastName avatarUrl bio stats')
    .lean();

  const { data, pagination } = processPaginatedResults(follows, limit, ['_id']);

  const followerList = data.map(f => f.follower as any);
  const followerIds = followerList.map(f => f._id.toString());

  let followingStatus = [];
  if (currentUserId) {
    followingStatus = await Follow.find({
      follower: currentUserId,
      following: { $in: followerIds },
    })
      .select('following')
      .lean();
  }

  const followingSet = new Set(followingStatus.map(f => (f.following as any).toString()));

  return {
    users: followerList.map(user => ({
      ...user,
      isFollowing: followingSet.has(user._id.toString()),
    })),
    pagination,
  };
};

const getFollowing = async ({
  userId,
  currentUserId,
  cursor = null,
  limit = 20,
}: {
  userId: string;
  currentUserId?: string;
  cursor?: string | null;
  limit?: number;
}) => {
  const query: Record<string, unknown> = { follower: userId };
  if (cursor) {
    Object.assign(query, buildCursorQuery(cursor, '_id', -1));
  }

  const follows = await Follow.find(query)
    .sort({ _id: -1 })
    .limit(limit + 1)
    .populate('following', 'username firstName lastName avatarUrl bio stats')
    .lean();

  const { data, pagination } = processPaginatedResults(follows, limit, ['_id']);

  const followingList = data.map(f => f.following as any);
  const followingIds = followingList.map(f => f._id.toString());

  let followedByStatus = [];
  if (currentUserId) {
    followedByStatus = await Follow.find({
      follower: { $in: followingIds },
      following: currentUserId,
    })
      .select('follower')
      .lean();
  }

  const followedBySet = new Set(followedByStatus.map(f => (f.follower as any).toString()));

  return {
    following: followingList.map(user => ({
      ...user,
      followsYou: followedBySet.has(user._id.toString()),
    })),
    pagination,
  };
};

const userService = {
  getUserByUsername,
  updateUserProfile,
  updateUserAvatar,
  getSuggestedUsers,
  toggleFollow,
  getUserRequotes,
  getFollowers,
  getFollowing,
};

export default userService;

import {
  Controller,
  Get,
  Post,
  Patch,
  Put,
  Param,
  Query,
  Body,
  Req,
  UseGuards,
  HttpStatus,
  UseInterceptors,
  UploadedFile,
} from "@nestjs/common";
import { FileInterceptor } from "@nestjs/platform-express";
import { diskStorage } from "multer";
import { extname } from "path";
import { UsersService } from "./users.service";
import { JwtAuthGuard } from "../auth/guards/jwt-auth.guard";
import { ResponseInterceptor } from "../../shared/interceptors/response.interceptor";
import { AuthenticatedRequest } from "../../shared/interfaces/authenticated-request.interface";

// Multer configuration for file uploads
const multerConfig = {
  storage: diskStorage({
    destination: "./uploads",
    filename: (req: any, file: any, cb: any) => {
      const randomName = Array(32)
        .fill(null)
        .map(() => Math.round(Math.random() * 16).toString(16))
        .join("");
      cb(null, `${randomName}${extname(file.originalname)}`);
    },
  }),
};

@Controller("user")
@UseInterceptors(ResponseInterceptor)
export class UsersController {
  constructor(private usersService: UsersService) {}

  @Get("suggested")
  @UseGuards(JwtAuthGuard)
  async getSuggestedUsers(
    @Req() req: AuthenticatedRequest,
    @Query("limit") limit?: string,
  ) {
    const userId = req.user?.id || null;
    const parsedLimit = parseInt(limit) || 8;
    const suggestedUsers = await this.usersService.getSuggestedUsers({
      userId,
      limit: parsedLimit,
    });
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "Suggested users retrieved successfully",
      data: suggestedUsers,
    };
  }

  @Get("suggested/public")
  async getPublicSuggestedUsers(@Query("limit") limit?: string) {
    const parsedLimit = parseInt(limit) || 8;
    const suggestedUsers = await this.usersService.getSuggestedUsers({
      userId: null,
      limit: parsedLimit,
    });
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "Public suggested users retrieved successfully",
      data: suggestedUsers,
    };
  }

  @Get("u/:username")
  async getUserByUsername(
    @Param("username") username: string,
    @Req() req: AuthenticatedRequest,
  ) {
    const user = await this.usersService.getUserByUsername(
      username,
      req.user ? req.user.id : null,
    );
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "User retrieved successfully",
      data: user,
    };
  }

  @Get("profile/me")
  @UseGuards(JwtAuthGuard)
  async getProfile(@Req() req: AuthenticatedRequest) {
    const userId = req.user.id;
    const user = await this.usersService.getUserByUsername(userId);
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "User profile retrieved successfully",
      data: user,
    };
  }

  @Patch("profile/me")
  @UseGuards(JwtAuthGuard)
  async updateProfile(@Req() req: AuthenticatedRequest, @Body() body: any) {
    const userId = req.user.id;
    const { firstName, lastName, email } = body;
    const updateUserProfile = await this.usersService.updateUserProfile(
      userId,
      {
        firstName,
        lastName,
        email,
      },
    );
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "User profile updated successfully",
      data: updateUserProfile,
    };
  }

  @Put("avatar")
  @UseGuards(JwtAuthGuard)
  @UseInterceptors(FileInterceptor("avatar", multerConfig))
  async updateAvatar(
    @Req() req: AuthenticatedRequest,
    @UploadedFile() avatarFile: any,
  ) {
    const userId = req.user.userId;

    if (!avatarFile) {
      throw new Error("No image file uploaded.");
    }

    const updatedUser = await this.usersService.updateUserAvatar(
      userId,
      avatarFile,
    );

    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: "Avatar updated successfully.",
      data: { avatarUrl: updatedUser.avatarUrl },
    };
  }

  @Post("follow/:id")
  @UseGuards(JwtAuthGuard)
  async toggleFollow(
    @Req() req: AuthenticatedRequest,
    @Param("id") targetId: string,
  ) {
    const followerId = req.user.userId;
    const result = await this.usersService.toggleFollow(followerId, targetId);
    return {
      success: true,
      statusCode: HttpStatus.OK,
      message: result.message,
      data: { followed: result.followed },
    };
  }

  @Get(":userId/requotes")
  @UseGuards(JwtAuthGuard)
  async getRequotes(
    @Param("userId") userId: string,
    @Req() req: AuthenticatedRequest,
    @Query("cursor") cursor?: string,
    @Query("limit") limit?: string,
