import winston from "winston";
import DailyRotateFile from "winston-daily-rotate-file";
import path from "path";
import fs from "fs";
import { AsyncLocalStorage } from "async_hooks";

const asyncLocalStorage = new AsyncLocalStorage<{ traceId?: string }>();

const getTraceId = (): string | undefined => {
  const context = asyncLocalStorage.getStore();
  return context?.traceId;
};

const withTraceId = (traceId: string, callback: () => void): void => {
  return asyncLocalStorage.run({ traceId }, callback);
};

const productionFormat = winston.format.combine(
  winston.format.timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  winston.format.errors({ stack: true }),
  winston.format.splat(),
  winston.format.printf(
    ({ timestamp, level, message, service, stack, ...meta }) => {
      const logObj: any = {
        timestamp,
        level,
        service: service || "unknown-service",
        message,
      };

      const traceId = getTraceId();
      if (traceId) {
        logObj.traceId = traceId;
      }

      if (stack) {
        logObj.stack = stack;
      }

      if (Object.keys(meta).length > 0) {
        logObj.metadata = meta;
      }

      return JSON.stringify(logObj);
    },
  ),
);

const developmentFormat = winston.format.combine(
  winston.format.timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  winston.format.errors({ stack: true }),
  winston.format.colorize(),
  winston.format.printf(
    ({ timestamp, level, message, service, stack, ...meta }) => {
      const traceId = getTraceId();
      const traceIdStr = traceId ? ` [${traceId}]` : "";
      const serviceStr = service ? ` [${service}]` : "";
      const stackStr = stack ? `\n${stack}` : "";
      const metaStr =
        Object.keys(meta).length > 0
          ? `\n${JSON.stringify(meta, null, 2)}`
          : "";

      return `${timestamp} ${level}${serviceStr}${traceIdStr}: ${message}${stackStr}${metaStr}`;
    },
  ),
);

const createLogger = (serviceName = "default-service"): winston.Logger => {
  const transports: winston.transport[] = [];

  const env = (process.env.NODE_ENV || "development").trim();
  const isProduction = env === "production";

  const enableFileLogging =
    (process.env.ENABLE_FILE_LOGGING || "").trim().toLowerCase() === "true" ||
    isProduction ||
    env === "development";

  console.log(
    `--- LOGGER DEBUG [${serviceName}]: NODE_ENV='${process.env.NODE_ENV}', ENABLE_FILE_LOGGING='${process.env.ENABLE_FILE_LOGGING}', Computed Flag=${enableFileLogging} ---`,
  );

  const logsDir = path.resolve(__dirname, "../../../logs");
  fs.mkdirSync(logsDir, { recursive: true });
  fs.mkdirSync(path.join(logsDir, "errors"), { recursive: true });
  console.log(`--- FILESYSTEM TARGET PATH: '${logsDir}' ---`);

  transports.push(
    new winston.transports.Console({
      format: isProduction ? productionFormat : developmentFormat,
      level: process.env.LOG_LEVEL || (isProduction ? "info" : "debug"),
    }),
  );

  if (enableFileLogging) {
    transports.push(
      new DailyRotateFile({
        filename: path.join(logsDir, "application-%DATE%.log"),
        datePattern: "YYYY-MM-DD",
        maxSize: "20m",
        maxFiles: "14d",
        zippedArchive: true,
        format: productionFormat,
        level: process.env.LOG_LEVEL || "info",
      }),
    );

    transports.push(
      new DailyRotateFile({
        filename: path.join(logsDir, "errors", "error-%DATE%.log"),
        datePattern: "YYYY-MM-DD",
        maxSize: "20m",
        maxFiles: "14d",
        zippedArchive: true,
        format: productionFormat,
        level: "error",
      }),
    );
  }

  return winston.createLogger({
    level: process.env.LOG_LEVEL || (isProduction ? "info" : "debug"),
    defaultMeta: { service: serviceName },
    transports,
    exceptionHandlers: [
      new winston.transports.Console({
        format: isProduction ? productionFormat : developmentFormat,
      }),
    ],
    rejectionHandlers: [
      new winston.transports.Console({
        format: isProduction ? productionFormat : developmentFormat,
      }),
    ],
  });
};

export { createLogger, getTraceId, withTraceId, asyncLocalStorage };

import { v4 as uuidv4 } from "uuid";
import { createLogger, withTraceId } from "./logger";
import { Request, Response, NextFunction } from "express";

const logger = createLogger("request-logger");

/**
 * Request Logger Middleware
 *
 * Usage in Express:
 *   const { requestLoggerMiddleware } = require('./src/shared/logging/requestLogger');
 *   app.use(requestLoggerMiddleware);
 */
const requestLoggerMiddleware = (req: Request, res: Response, next: NextFunction) => {
  // ============== STEP 1: EXTRACT OR GENERATE CORRELATION ID ==============
  // Check if correlation ID exists in header (from upstream service/client)
  let traceId = req.headers["x-correlation-id"] || req.headers["x-trace-id"];

  // Generate new correlation ID if not provided
  if (!traceId) {
    traceId = `${Date.now()}-${uuidv4()}`;
  }

  // Attach to request object for access in route handlers
  req.traceId = traceId;
  req.correlationId = traceId; // Alternative naming convention

  // Add to response headers (for client/upstream services to track)
  res.setHeader("X-Correlation-ID", traceId);
  res.setHeader("X-Trace-ID", traceId);

  // ============== STEP 2: RECORD REQUEST TIMING ==============
  const requestStart = Date.now();

  // ============== STEP 3: INTERCEPT RESPONSE ==============
  // Capture the original res.end to log after response is sent
  const originalEnd = res.end;
  res.end = function (...args) {
    const responseTime = Date.now() - requestStart;

    // Call original end
    originalEnd.apply(res, args);

    // ============== STEP 4: LOG REQUEST WITHIN TRACE CONTEXT ==============
    // This ensures all logs generated during request handling include the traceId
    withTraceId(traceId, () => {
      const logData = {
        method: req.method,
        url: req.originalUrl || req.url,
        statusCode: res.statusCode,
        responseTime: `${responseTime}ms`,
        ip: req.ip || req.connection.remoteAddress,
        userAgent: req.get("user-agent"),
        correlationId: traceId,
      };

      // Determine log level based on status code
      if (res.statusCode >= 500) {
        logger.error("HTTP Request", {
          ...logData,
          errorStatus: true,
        });
      } else if (res.statusCode >= 400) {
        logger.warn("HTTP Request", {
          ...logData,
          clientError: true,
        });
      } else {
        logger.info("HTTP Request", logData);
      }
    });
  };

  // ============== STEP 5: WRAP next() IN TRACE CONTEXT ==============
  // Ensures all async handlers have access to traceId via AsyncLocalStorage
  withTraceId(traceId, () => {
    next();
  });
};

/**
 * Alternative: Express async middleware wrapper for cleaner error handling
 * Use this if you need better error propagation
 */
const asyncRequestLoggerMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  const traceId = req.headers["x-correlation-id"] || `${Date.now()}-${uuidv4()}`;
  req.traceId = traceId;
  req.correlationId = traceId;
  res.setHeader("X-Correlation-ID", traceId);

  const requestStart = Date.now();
  const originalEnd = res.end;

  res.end = function (...args) {
    const responseTime = Date.now() - requestStart;
    originalEnd.apply(res, args);

    withTraceId(traceId, () => {
      const logData = {
        method: req.method,
        url: req.originalUrl || req.url,
        statusCode: res.statusCode,
        responseTime: `${responseTime}ms`,
        correlationId: traceId,
      };

      if (res.statusCode >= 500) {
        logger.error("HTTP Request Error", logData);
      } else if (res.statusCode >= 400) {
        logger.warn("HTTP Request Warning", logData);
      } else {
        logger.info("HTTP Request Success", logData);
      }
    });
  };

  withTraceId(traceId, () => next());
};

/**
 * Manual Correlation ID setter (for testing or manual control)
 *
 * Usage:
 *   app.use(setCorrelationId);
 */
const setCorrelationId = (req: Request, res: Response, next: NextFunction) => {
  const traceId = req.headers["x-correlation-id"] || `${Date.now()}-${uuidv4()}`;
  // attach to request as any extension for middleware compatibility
  (req as any).traceId = traceId;
  res.setHeader("X-Correlation-ID", traceId);
  next();
};

