import jwt from "jsonwebtoken";
import { Request, Response, NextFunction } from "express";

const JWT_SECRET = process.env.JWT_SECRET;

/* eslint-disable @typescript-eslint/no-namespace */
declare global {
  namespace Express {
    interface Request {
      user?: any;
    }
  }
}

const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res
      .status(401)
      .json({ message: "Access token missing or malformed" });
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = jwt.verify(token, JWT_SECRET || "");
    req.user = decoded;
    next();
  } catch {
    return res.status(403).json({ message: "Invalid or expired access token" });
  }
};

export default authMiddleware;

import { createLogger, withTraceId } from "../logging/logger";
import { errorResponse } from "../utils/responseFormatter.util";
import { Request, Response, NextFunction } from "express";

const logger = createLogger("request-logger");

/* eslint-disable @typescript-eslint/no-namespace */
declare global {
  namespace Express {
    interface Request {
      traceId?: string;
      user?: any;
    }
  }
}

const requestLogger = (req: Request, res: Response, next: NextFunction) => {
  const startAt = process.hrtime.bigint();
  const userId = req.user?.id || req.user?._id || "anonymous";

  const traceId =
    (req.headers["x-correlation-id"] as string) ||
    (req.headers["x-trace-id"] as string) ||
    `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  req.traceId = traceId;
  res.setHeader("X-Correlation-ID", traceId);

  res.on("finish", () => {
    const durationMs = Number(process.hrtime.bigint() - startAt) / 1e6;

    withTraceId(traceId, () => {
      logger.info("HTTP request completed", {
        method: req.method,
        url: req.originalUrl,
        statusCode: res.statusCode,
        durationMs: Number(durationMs.toFixed(2)),
        userId,
        route: req.route?.path || req.originalUrl,
        ip: req.ip,
        userAgent: req.headers["user-agent"],
        referer: req.headers.referer || req.headers.referrer,
      });
    });
  });

  res.on("close", () => {
    if (!res.writableEnded) {
      withTraceId(traceId, () => {
        logger.warn("HTTP request closed before response finished", {
          method: req.method,
          url: req.originalUrl,
          userId,
          ip: req.ip,
        });
      });
    }
  });

  withTraceId(traceId, () => {
    next();
  });
};

const notFoundHandler = (req: Request, res: Response) => {
  return errorResponse(res, 404, "Route not found");
};

const errorHandler = (
  err: any,
  req: Request,
  res: Response,
  _next: NextFunction,
) => {
  const status = err.status || 500;
  const userId = req.user?.id || req.user?._id || "anonymous";

  const traceId = req.traceId || "no-trace";
  withTraceId(traceId, () => {
    logger.error("Unhandled request error", {
      status,
      method: req.method,
      path: req.originalUrl,
      userId,
      error: err,
    });
  });

  const errors =
    process.env.NODE_ENV === "production"
      ? []
      : [{ message: err.message, stack: err.stack }];

  return errorResponse(
    res,
    status,
    err.message || "Internal server error",
    errors,
  );
};

export { requestLogger, notFoundHandler, errorHandler };

import { redis } from "../utils/redis.utils";
import { Request, Response, NextFunction } from "express";

interface RateLimiterConfig {
  actionName: string;
  burstWindowMs: number;
  burstLimit: number;
  sustainedWindowMs: number;
  sustainedLimit: number;
  identifier?: "ip" | "userId";
}

const createRateLimiter = ({
  actionName,
  burstWindowMs,
  burstLimit,
  sustainedWindowMs,
  sustainedLimit,
  identifier = "ip",
}: RateLimiterConfig) => {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      const id = identifier === "userId" && req.user ? req.user.id : req.ip;

      const burstKey = `qotes:ratelimit:${actionName}:burst:${id}`;
      const sustainedKey = `qotes:ratelimit:${actionName}:sustain:${id}`;

      const allowed = await (redis as any).slidingWindowRateLimit(
        burstKey,
        sustainedKey,
        Date.now(),
        burstWindowMs,
        burstLimit,
        sustainedWindowMs,
        sustainedLimit,
      );

      if (!allowed) {
        return res.status(429).json({
          success: false,
          message: `Too many requests for ${actionName}. Please try again later.`,
        });
      }

      next();
    } catch (error: any) {
      console.error(`Rate Limiter Error (${actionName}):`, error.message);
      next();
    }
  };
};

export { createRateLimiter };

