/**
 * Async Handler Utility
 * Wraps async Express route handlers to automatically catch errors
 * and pass them to the Express error handling middleware.
 */
const asyncHandler =
  (fn: (req: Request, res: Response, next: NextFunction) => Promise<any>) =>
  (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };

export default asyncHandler;

/**
 * Cursor Utility for consistent cursor-based pagination
 * Supports single-field and compound cursors with proper encoding/decoding
 */

export interface CursorData {
  [key: string]: string | number | Date;
}

/**
 * Encode cursor data to a base64 string
 * @param data - Object containing cursor fields (e.g., { createdAt, id })
 * @returns Base64 encoded string
 */
export function encodeCursor(data: CursorData): string {
  const jsonString = JSON.stringify(data);
  return Buffer.from(jsonString).toString("base64");
}

/**
 * Decode base64 cursor string to object
 * @param cursor - Base64 encoded cursor string
 * @returns Decoded cursor data object
 */
export function decodeCursor(cursor: string): CursorData {
  const jsonString = Buffer.from(cursor, "base64").toString("utf-8");
  return JSON.parse(jsonString);
}

/**
 * Build MongoDB query from cursor for single-field pagination
 * @param cursor - Cursor string or null
 * @param field - Field name to paginate on (e.g., 'createdAt', '_id')
 * @param direction - Sort direction: -1 for descending, 1 for ascending
 * @returns MongoDB query object
 */
export function buildCursorQuery(
  cursor: string | null,
  field: string,
  direction: -1 | 1 = -1,
): any {
  if (!cursor) return {};

  const decoded = decodeCursor(cursor);
  const value = decoded[field];

  if (direction === -1) {
    return { [field]: { $lt: value } };
  } else {
    return { [field]: { $gt: value } };
  }
}

/**
 * Build MongoDB query from cursor for compound pagination (tie-breaker)
 * @param cursor - Cursor string or null
 * @param fields - Array of field names in sort order (e.g., ['createdAt', '_id'])
 * @param directions - Array of sort directions matching fields
 * @returns MongoDB query object with $or for tie-breaking
 */
export function buildCompoundCursorQuery(
  cursor: string | null,
  fields: string[],
  directions: (-1 | 1)[],
): any {
  if (!cursor) return {};

  const decoded = decodeCursor(cursor);
  const query: any = { $or: [] };

  // Build compound query for tie-breaking
  for (let i = 0; i < fields.length; i++) {
    const field = fields[i];
    const direction = directions[i];
    const value = decoded[field];

    const condition: any = {};

    // Add equality conditions for all previous fields
    for (let j = 0; j < i; j++) {
      condition[fields[j]] = decoded[fields[j]];
    }

    // Add inequality condition for current field
    if (direction === -1) {
      condition[field] = { $lt: value };
    } else {
      condition[field] = { $gt: value };
    }

    query.$or.push(condition);
  }

  return query;
}

/**
 * Extract next cursor from results
 * @param results - Array of results
 * @param limit - Original limit requested
 * @param fields - Fields to include in cursor (for compound cursors)
 * @returns Next cursor string or null
 */
export function getNextCursor(
  results: any[],
  limit: number,
  fields: string[] = ["createdAt"],
): string | null {
  if (results.length <= limit) return null;

  const lastItem = results[results.length - 1];
  const cursorData: CursorData = {};

  fields.forEach((field) => {
    cursorData[field] = lastItem[field];
  });

  return encodeCursor(cursorData);
}

/**
 * Standard pagination response structure
 */
export interface PaginationResponse {
  nextCursor: string | null;
  hasMore: boolean;
}

/**
 * Process paginated results - removes extra item and builds pagination response
 * @param results - Results array with limit + 1 items
 * @param limit - Original limit requested
 * @param cursorFields - Fields to include in next cursor
 * @returns Object with results and pagination info
 */
export function processPaginatedResults<T>(
  results: T[],
  limit: number,
  cursorFields: string[] = ["createdAt"],
): { data: T[]; pagination: PaginationResponse } {
  const hasMore = results.length > limit;
  const data = hasMore ? results.slice(0, limit) : results;

  return {
    data,
    pagination: {
      nextCursor:
        hasMore && data.length > 0
          ? encodeCursor(
            cursorFields.reduce((acc, field) => {
              acc[field] = (data[data.length - 1] as any)[field];
              return acc;
            }, {} as CursorData),
          )
          : null,
      hasMore,
    },
  };
}

import Redis from "ioredis";
import dotenv from "dotenv";
import logger from "./logger.util";

dotenv.config();

const redis = new Redis({
  host: process.env.REDIS_HOST || "127.0.0.1",
  port: parseInt(process.env.REDIS_PORT || "6379"),
  maxRetriesPerRequest: null,
  enableReadyCheck: true,
  retryStrategy(times: number) {
    return Math.min(times * 50, 2000);
  },
});

redis.on("connect", () => {
  logger.info("Redis connected", {
    service: "redis",
    host: process.env.REDIS_HOST || "127.0.0.1",
    port: process.env.REDIS_PORT || 6379,
  });
});

redis.on("ready", () => {
  logger.info("Redis ready to accept commands", {
    service: "redis",
  });
});

redis.on("error", (error: Error) => {
  logger.error("Redis connection error", {
    service: "redis",
    error,
  });
});

redis.on("reconnecting", (delay: number) => {
  logger.warn("Redis reconnecting", {
    service: "redis",
    delay,
  });
});

// Serialization helpers
const serialize = (value: any): string => {
  if (typeof value === 'string') return value;
  return JSON.stringify(value);
};

const deserialize = <T>(value: string | null): T | null => {
  if (!value) return null;
  try {
    return JSON.parse(value) as T;
  } catch {
    return value as T;
  }
};

// Generic cache operations with automatic serialization
const cacheGetTyped = async <T>(key: string): Promise<T | null> => {
  try {
    const value = await redis.get(key);
    logger.debug("Redis cache lookup", {
      service: "redis",
      operation: "getTyped",
      key,
      hit: value !== null,
    });
    return deserialize<T>(value);
  } catch (error) {
    logger.error("Redis cache get typed failed", {
      service: "redis",
      operation: "getTyped",
      key,
      error,
    });
    return null;
  }
};

const cacheSetTyped = async <T>(
  key: string,
  value: T,
  ttlSeconds?: number,
): Promise<boolean> => {
  try {
    const serialized = serialize(value);
    const result = ttlSeconds
      ? await redis.set(key, serialized, "EX", ttlSeconds)
      : await redis.set(key, serialized);
    logger.debug("Redis cache write", {
      service: "redis",
      operation: "setTyped",
      key,
      ttlSeconds,
      result,
    });
    return result === "OK";
  } catch (error) {
    logger.error("Redis cache set typed failed", {
      service: "redis",
      operation: "setTyped",
      key,
      ttlSeconds,
      error,
    });
    return false;
  }
};

const cacheGetOrSet = async <T>(
  key: string,
  factory: () => Promise<T>,
  ttlSeconds?: number,
): Promise<T> => {
  try {
    const cached = await cacheGetTyped<T>(key);
    if (cached !== null) {
      return cached;
    }
    
    const value = await factory();
    await cacheSetTyped(key, value, ttlSeconds);
    return value;
  } catch (error) {
    logger.error("Redis cache getOrSet failed", {
      service: "redis",
      operation: "getOrSet",
      key,
      error,
    });
    // Return factory result as fallback
    return await factory();
  }
};

const cacheDelPattern = async (pattern: string): Promise<number> => {
  try {
    const keys = await redis.keys(pattern);
    if (keys.length === 0) return 0;
    
    const result = await redis.del(...keys);
    logger.debug("Redis cache pattern delete", {
      service: "redis",
      operation: "delPattern",
      pattern,
      keysCount: keys.length,
      result,
    });
    return result;
  } catch (error) {
    logger.error("Redis cache del pattern failed", {
      service: "redis",
      operation: "delPattern",
      pattern,
      error,
    });
    return 0;
  }
};

const cacheExpire = async (key: string, ttlSeconds: number): Promise<boolean> => {
  try {
    const result = await redis.expire(key, ttlSeconds);
    logger.debug("Redis cache expire", {
      service: "redis",
      operation: "expire",
      key,
      ttlSeconds,
      result,
    });
    return result === 1;
  } catch (error) {
    logger.error("Redis cache expire failed", {
      service: "redis",
      operation: "expire",
      key,
      ttlSeconds,
      error,
    });
    return false;
  }
};

const cacheTTL = async (key: string): Promise<number> => {
