import dotenv from "dotenv";
import fetch from "node-fetch";
import { Worker } from "bullmq";
import { redis } from "../shared/utils/redis.utils";
import logger from "../shared/utils/logger.util";
import Quote from "../models/quote.model";

dotenv.config();

const queueName = "content-sync-queue";

const worker = new Worker(
  queueName,
  async (job: any) => {
    logger.info("Content sync job started", {
      queue: queueName,
      jobId: job.id,
      data: job.data,
    });

    const sourceUrl = process.env.CONTENT_SYNC_URL;
    if (!sourceUrl) {
      throw new Error("CONTENT_SYNC_URL is not configured");
    }

    const response = await fetch(sourceUrl, { timeout: 30000 } as any);
    if (!response.ok) {
      throw new Error(
        `Failed to fetch content sync source: ${response.status} ${response.statusText}`,
      );
    }

    const payload = await response.json();
    if (!Array.isArray(payload)) {
      throw new Error(
        "Invalid content sync response format: expected JSON array",
      );
    }

    const syncResults: any[] = [];
    for (const item of payload) {
      if (!item.text) {
        continue;
      }

      const quoteData = {
        text: item.text,
        author: item.author || "Anonymous",
        category: item.category || "external",
        hashtags: item.hashtags || [],
        taggedUsers: item.taggedUsers || [],
      };

      const syncedQuote = await Quote.findOneAndUpdate(
        { text: quoteData.text, author: quoteData.author },
        { $setOnInsert: quoteData },
        { upsert: true, new: true, setDefaultsOnInsert: true },
      );

      syncResults.push({
        quoteId: syncedQuote._id.toString(),
        createdAt: syncedQuote.createdAt,
      });
    }

    logger.info("Content sync job completed", {
      queue: queueName,
      jobId: job.id,
      syncedCount: syncResults.length,
    });

    return { syncedCount: syncResults.length };
  },
  {
    connection: redis,
    concurrency: 2,
    lockDuration: 300000,
  },
);

worker.on("completed", (job: any) => {
  logger.info("Content sync job completed", {
    queue: queueName,
    jobId: job.id,
    returnValue: job.returnvalue,
  });
});

worker.on("failed", (job: any, err: Error) => {
  logger.error("Content sync job failed", {
    queue: queueName,
    jobId: job?.id,
    failedReason: err?.message,
    stack: err?.stack,
  });
});

worker.on("stalled", (job: any) => {
  logger.warn("Content sync job stalled", {
    queue: queueName,
    jobId: job?.id,
  });
});

worker.on("error", (error: Error) => {
  logger.error("Content sync worker error", { queue: queueName, error });
});

import dotenv from "dotenv";
import { Worker } from "bullmq";
import { redis } from "../shared/utils/redis.utils";
import logger from "../shared/utils/logger.util";
import { addScheduledJob } from "../shared/queues/scheduledCron.queue";
import { addContentSyncJob } from "../shared/queues/contentSync.queue";
import { enqueueNotificationJob } from "../shared/queues/quoteNotifications.queue";
import Quote from "../models/quote.model";
import User from "../models/user.model";

dotenv.config();

const queueName = "scheduled-cron-queue";

const worker = new Worker(
  queueName,
  async (job: any) => {
    logger.info("Running scheduled job", {
      queue: queueName,
      jobId: job.id,
      name: job.name,
      data: job.data,
    });

    if (job.name === "daily-quote-of-day") {
      const latestQuote = await Quote.findOne({ isHiddenBySystem: false })
        .sort({ createdAt: -1 })
        .lean();
      if (!latestQuote) {
        logger.warn("No quote available for daily quote job");
        return { skipped: true };
      }

      const recipients = await User.find({
        email: { $exists: true, $ne: "" },
        isBanned: false,
      })
        .limit(100)
        .lean();

      await Promise.all(
        recipients.map((recipient: any) =>
          enqueueNotificationJob(
            {
              type: "generic-email",
              recipientId: recipient._id,
              subject: "Daily Quote of the Day",
              body: `<p>Hi ${recipient.username || "friend"},</p><p>Here is today's featured quote:</p><blockquote>${latestQuote.text}</blockquote><p>— ${latestQuote.author}</p>`,
            },
            { attempts: 2, backoff: { type: "exponential", delay: 2000 } },
          ),
        ),
      );

      return { delivered: recipients.length };
    }

    if (job.name === "delayed-onboarding") {
      const { userId, step } = job.data;
      if (!userId) {
        throw new Error("delayed-onboarding job requires userId");
      }

      const recipient = await User.findById(userId).lean();
      if (!recipient || !recipient.email) {
        return { skipped: true };
      }

      return enqueueNotificationJob(
        {
          type: "generic-email",
          recipientId: recipient._id,
          subject: "Welcome to Qotes",
          body: `<p>Hi ${recipient.username || "there"},</p><p>This is your next onboarding step: ${step || "Start exploring quotes."}</p>`,
        },
        { attempts: 1, backoff: { type: "exponential", delay: 1000 } },
      );
    }

    if (job.name === "content-sync-trigger") {
      await addContentSyncJob({ type: "content-sync" });
      return { triggered: true };
    }

    throw new Error(`Unknown scheduled job: ${job.name}`);
  },
  {
    connection: redis,
    concurrency: 2,
    lockDuration: 120000,
  },
);

worker.on("completed", (job: any) => {
  logger.info("Scheduled job completed", {
    queue: queueName,
    jobId: job.id,
    name: job.name,
    returnValue: job.returnvalue,
  });
});

worker.on("failed", (job: any, err: Error) => {
  logger.error("Scheduled job failed", {
    queue: queueName,
    jobId: job?.id,
    name: job?.name,
    failedReason: err?.message,
    stack: err?.stack,
  });
});

worker.on("stalled", (job: any) => {
  logger.warn("Scheduled job stalled", {
    queue: queueName,
    jobId: job?.id,
    name: job?.name,
  });
});

worker.on("error", (error: Error) => {
  logger.error("Scheduled cron worker error", { queue: queueName, error });
});

const dailyCron = process.env.DAILY_QUOTE_CRON || "0 8 * * *";
const contentSyncCron = process.env.CONTENT_SYNC_CRON || "0 */6 * * *";

void (async () => {
  try {
    await addScheduledJob(
      "daily-quote-of-day",
      {},
      {
        jobId: "daily-quote-of-day",
        repeat: { cron: dailyCron, tz: process.env.TIMEZONE || "UTC" },
        removeOnComplete: { age: 3600 },
        removeOnFail: { age: 86400 },
      },
    );
    await addScheduledJob(
      "content-sync-trigger",
      {},
      {
        jobId: "content-sync-trigger",
        repeat: { cron: contentSyncCron, tz: process.env.TIMEZONE || "UTC" },
        removeOnComplete: { age: 3600 },
        removeOnFail: { age: 86400 },
      },
    );
    logger.info("Scheduled cron repeatable jobs created", {
      dailyCron,
      contentSyncCron,
    });
  } catch (error: any) {
    logger.error("Failed to add repeatable scheduled jobs", { error });
  }
})();

import dotenv from "dotenv";
import os from "os";
import path from "path";
import { promises as fs } from "fs";
import sharp from "sharp";
import { Worker } from "bullmq";
import { redis } from "../shared/utils/redis.utils";
import logger from "../shared/utils/logger.util";
import Quote from "../models/quote.model";
import cloudinaryService from "../infrastructure/media/cloudinary.service";

dotenv.config();

const queueName = "image-generation-queue";
const cpuCount = os.cpus().length || 2;
const concurrency = Math.min(Math.max(2, cpuCount - 1), 4);

const renderQuoteSvg = (text: string, author = "Anonymous"): string => {
  const escapedText = text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
  const escapedAuthor = author
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg width="1200" height="630" viewBox="0 0 1200 630" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#0f172a" />
      <stop offset="100%" stop-color="#1e293b" />
    </linearGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#bg)" />
  <rect x="60" y="60" width="1080" height="510" rx="40" ry="40" fill="#111827" opacity="0.95" />
  <foreignObject x="100" y="120" width="1000" height="360">
    <div xmlns="http://www.w3.org/1999/xhtml" style="font-family: Inter, system-ui, sans-serif; color: #f8fafc; font-size: 48px; line-height: 1.2; white-space: pre-wrap; overflow-wrap: break-word;">
      ${escapedText}
    </div>
  </foreignObject>
  <text x="100" y="520" fill="#94a3b8" font-family="Inter, system-ui, sans-serif" font-size="32">— ${escapedAuthor}</text>
</svg>`;
};

const worker = new Worker(
  queueName,
  async (job: any) => {
    logger.info("Starting image generation job", {
      queue: queueName,
      jobId: job.id,
      data: job.data,
    });

    const { quoteId, outputFolder = "uploads/quote-images" } = job.data;
    const quote = await Quote.findById(quoteId).lean();
    if (!quote) {
      throw new Error(`Quote not found: ${quoteId}`);
    }

    const svg = renderQuoteSvg(quote.text || "", quote.author || "Anonymous");
    const outputDir = path.resolve(process.cwd(), outputFolder);
    await fs.mkdir(outputDir, { recursive: true });

    const outputPath = path.join(outputDir, `${quoteId}-${Date.now()}.png`);
    await sharp(Buffer.from(svg)).png({ quality: 90 }).toFile(outputPath);

    let uploadedUrl;
    try {
      uploadedUrl = await cloudinaryService.uploadImage(
        outputPath,
        "qotes-app/shareable-quotes",
      );
    } finally {
      await fs.rm(outputPath, { force: true }).catch(() => {});
    }

    logger.info("Completed image generation job", {
      queue: queueName,
      jobId: job.id,
      uploadedUrl,
    });

    return { imageUrl: uploadedUrl };
  },
  {
    connection: redis,
    concurrency,
    lockDuration: 600000,
  },
);

worker.on("completed", (job: any) => {
  logger.info("Image generation job completed", {
    queue: queueName,
    jobId: job.id,
    returnValue: job.returnvalue,
  });
});

worker.on("failed", (job: any, err: Error) => {
  logger.error("Image generation job failed", {
    queue: queueName,
    jobId: job?.id,
    failedReason: err?.message,
    stack: err?.stack,
  });
});

worker.on("stalled", (job: any) => {
  logger.warn("Image generation job stalled", {
    queue: queueName,
    jobId: job?.id,
  });
});

worker.on("error", (error: Error) => {
  logger.error("Image generation worker error", { queue: queueName, error });
});

import dotenv from "dotenv";
import { connectToDatabase } from "../config/database";
import { kafka } from "../infrastructure/kafka/config/kafka.config";
import Follow from "../models/follow.model";
import { redis } from "../shared/utils/redis.utils";

dotenv.config();

const consumer = kafka.consumer({ groupId: "cache-warmup-group" });

const runCacheWorker = async (): Promise<void> => {
  try {
    await connectToDatabase();

    await consumer.connect();
    console.log("Cache Worker connected to Kafka");

    await consumer.subscribe({ topic: "auth-events", fromBeginning: true });
    console.log("Cache Worker subscribed to auth-events topic");

    await consumer.run({
      eachMessage: async ({ topic, partition, message }) => {
        const prefix = `${topic}[${partition} | ${message.offset}]`;
        console.log(`- ${prefix}: ${message.key} / ${message.value}`);

        try {
          const { userId, action } = JSON.parse(
            message.value?.toString() || "{}",
          );

          if (action === "login_warmup") {
            const cacheKey = `following:${userId}`;

            const exists = await redis.exists(cacheKey);
            if (!exists) {
              const following = await Follow.find({
                follower: userId,
              }).distinct("following");

              if (following.length > 0) {
                const ids = following.map((id: any) => id.toString());

                await redis
                  .pipeline()
                  .sadd(cacheKey, ...ids)
                  .expire(cacheKey, 86400)
                  .exec();

                console.log(`Warmed up cache for user: ${userId}`);
              }
            }
          }
        } catch (parseErr: any) {
          console.error("Error processing message:", parseErr);
        }
      },
    });
  } catch (error: any) {
    console.error("Kafka Worker Error:", error);
  }
};

runCacheWorker().catch((err: Error) => {
  console.error("Cache worker failed to start:", err);
  process.exit(1);
});

