dotenv.config();

const queueName = "quote-notifications-queue";

const worker = new Worker(
  queueName,
  async (job: any) => {
    logger.info("Processing notification job", {
      queue: queueName,
      jobId: job.id,
      name: job.name,
      data: job.data,
    });

    const {
      type,
      recipientId,
      actorId,
      quoteId,
      email,
      link,
      subject,
      body,
      html,
      text,
    } = job.data;

    switch (type) {
      case "password-reset-email": {
        if (!email || !link) {
          throw new Error("Missing email or reset link for password reset job");
        }
        return sendEmail({
          to: email,
          subject: subject || "Reset your password",
          html:
            body ||
            `<p>Please reset your password <a href="${link}">here</a>.</p>`,
          text: `Reset your password: ${link}`,
        });
      }
      case "quote-like": {
        if (!recipientId || !actorId || !quoteId) {
          throw new Error("Missing required quote-like payload fields");
        }

        const recipient = await User.findById(recipientId).lean();
        const actor = await User.findById(actorId).lean();
        const quote = await Quote.findById(quoteId).lean();

        if (!recipient || !actor || !quote) {
          throw new Error(
            "Quote-like notification actor/recipient/quote missing",
          );
        }

        try {
          await notificationService.createNotification({
            recipient: recipientId,
            sender: actorId,
            type: NOTIFICATION_TYPES.LIKE_QUOTE,
            message: `${actor.username || actor.email || "Someone"} liked your quote`,
            referenceId: quoteId,
            referenceType: REFERENCE_TYPES.QUOTE,
            metadata: {
              quoteText: quote.text,
              quoteAuthor: quote.author,
              senderName: actor.username,
            },
          });
        } catch (notifError: any) {
          logger.error("Failed to create in-app notification for quote-like", {
            error: notifError.message,
          });
        }

        const notificationBody = `Your quote was liked by ${actor.username || actor.email || "someone"}.`;
        const emailBody = `<p>Hi ${recipient.username || ""},</p><p>${notificationBody}</p><p>Quote: ${quote.text}</p>`;

        if (recipient.email) {
          return sendEmail({
            to: recipient.email,
            subject: subject || "Your quote got a new like",
            html: body || emailBody,
            text: `${notificationBody}\n\n${quote.text}`,
          });
        }

        logger.info(
          "Skipping email for quote-like notification because recipient has no email",
          {
            recipientId,
            quoteId,
          },
        );
        return { skipped: true, emailSkipped: true };
      }
      case "user-follow": {
        if (!recipientId || !actorId) {
          throw new Error("Missing required user-follow payload fields");
        }

        const recipient = await User.findById(recipientId).lean();
        const actor = await User.findById(actorId).lean();

        if (!recipient || !actor) {
          throw new Error(
            "User-follow notification actor or recipient missing",
          );
        }

        try {
          await notificationService.createNotification({
            recipient: recipientId,
            sender: actorId,
            type: NOTIFICATION_TYPES.FOLLOW_USER,
            message: `${actor.username || actor.email || "Someone"} started following you`,
            referenceId: actorId,
            referenceType: REFERENCE_TYPES.USER,
            metadata: {
              senderName: actor.username,
              senderUsername: actor.username,
            },
          });
        } catch (notifError: any) {
          logger.error("Failed to create in-app notification for user-follow", {
            error: notifError.message,
          });
        }

        const notificationBody = `${actor.username || actor.email || "Someone"} started following you.`;
        const emailBody = `<p>Hi ${recipient.username || ""},</p><p>${notificationBody}</p>`;

        if (recipient.email) {
          return sendEmail({
            to: recipient.email,
            subject: subject || "You have a new follower",
            html: body || emailBody,
            text: notificationBody,
          });
        }

        logger.info(
          "Skipping email for follow notification because recipient has no email",
          {
            recipientId,
          },
        );
        return { skipped: true, emailSkipped: true };
      }
      case "generic-email": {
        const recipient = recipientId
          ? await User.findById(recipientId).lean()
          : null;
        const targetEmail = email || recipient?.email;

        if (!targetEmail) {
          throw new Error("Missing email address for generic email job");
        }

        return sendEmail({
          to: targetEmail,
          subject: subject || "Notification from Qotes",
          html:
            html || body || `<p>${body || "You have a new notification."}</p>`,
          text: text || body || "You have a new notification.",
        });
      }
      default:
        throw new Error(`Unsupported notification job type: ${type}`);
    }
  },
  {
    connection: redis,
    concurrency: 5,
    lockDuration: 120000,
  },
);

worker.on("completed", (job: any) => {
  logger.info("Notification job completed", {
    queue: queueName,
    jobId: job.id,
    returnValue: job.returnvalue,
  });
});

worker.on("failed", (job: any, err: Error) => {
  logger.error("Notification job failed", {
    queue: queueName,
    jobId: job?.id,
    failedReason: err?.message,
    stack: err?.stack,
  });
});

worker.on("stalled", (job: any) => {
  logger.warn("Notification job stalled", {
    queue: queueName,
    jobId: job?.id,
  });
});

worker.on("error", (error: Error) => {
  logger.error("Notification worker error", { queue: queueName, error });
});

import dotenv from "dotenv";
import mongoose from "mongoose";
import logger from "../shared/utils/logger.util";
import { connectToDatabase } from "../config/database";
import { kafka, producer } from "../infrastructure/kafka/config/kafka.config";
import Reaction from "../models/reaction.model";
import Quote from "../models/quote.model";

dotenv.config();

const DLQ_TOPIC = "reaction-events-dlq";
const consumer = kafka.consumer({ groupId: "reaction-persistence-group" });

interface MessageMeta {
  topic: string;
  partition: number;
  offset: string;
  key: string | null;
  replayedAt: string | null;
  traceId: string | null;
  userId: string | null;
  quoteId: string | null;
  action: string | null;
}

interface ReactionPayload {
  userId: string;
  quoteId: string;
  type: string;
  action: string;
  oldType?: string;
}

const buildMessageMeta = (
  topic: string,
  partition: number,
  message: any,
  payload: ReactionPayload,
): MessageMeta => ({
  topic,
  partition,
  offset: message.offset,
  key: message.key?.toString() || null,
  replayedAt: message.headers?.replayedAt?.toString() || null,
  traceId: message.headers?.traceId?.toString() || null,
  userId: payload?.userId || null,
  quoteId: payload?.quoteId || null,
  action: payload?.action || null,
});

const runReactionWorker = async (): Promise<void> => {
  await connectToDatabase();
  await consumer.connect();
  await producer.connect();
  await consumer.subscribe({ topic: "reaction-events", fromBeginning: false });

  logger.info("Reaction consumer worker started", {
    service: "reaction-worker",
    groupId: "reaction-persistence-group",
    topic: "reaction-events",
  });

  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      const payload: ReactionPayload = JSON.parse(
        message.value?.toString() || "{}",
      );
      const meta = buildMessageMeta(topic, partition, message, payload);

      logger.info("Kafka reaction event received", meta);

      if (meta.replayedAt) {
        logger.debug("Processing replayed Kafka message", meta);
      }

      try {
        const userObjId = new mongoose.Types.ObjectId(payload.userId);
        const quoteObjId = new mongoose.Types.ObjectId(payload.quoteId);

        if (payload.action === "added") {
          const existing = await Reaction.findOneAndUpdate(
            { user: userObjId, quote: quoteObjId },
            { type: payload.type },
            { upsert: true, new: false },
          );

          if (!existing) {
            const update: any = { [`reactions.${payload.type}`]: 1 };
            if (payload.type === "like") update.likes = 1;

            await Quote.findByIdAndUpdate(quoteObjId, { $inc: update });
            logger.info("Processed reaction added event", {
              ...meta,
              result: "added",
              type: payload.type,
            });
          }
        } else if (payload.action === "updated") {
          const update: any = {
            [`reactions.${payload.oldType}`]: -1,
            [`reactions.${payload.type}`]: 1,
          };

          if (payload.oldType === "like") update.likes = -1;
          if (payload.type === "like") update.likes = 1;

          await Promise.all([
            Reaction.updateOne(
              { user: userObjId, quote: quoteObjId },
              { type: payload.type },
            ),
            Quote.findByIdAndUpdate(quoteObjId, { $inc: update }),
          ]);

          logger.info("Processed reaction updated event", {
            ...meta,
            result: "updated",
            oldType: payload.oldType,
            type: payload.type,
          });
        } else if (payload.action === "removed") {
          const deleted = await Reaction.findOneAndDelete({
            user: userObjId,
            quote: quoteObjId,
          });

          if (deleted) {
            const update: any = { [`reactions.${payload.type}`]: -1 };
            if (payload.type === "like") update.likes = -1;

            await Quote.findByIdAndUpdate(quoteObjId, { $inc: update });
            logger.info("Processed reaction removed event", {
              ...meta,
              result: "removed",
            });
          }
        } else {
          logger.warn("Received unsupported reaction action", meta);
        }
      } catch (err: any) {
        logger.error("Kafka reaction processing failed, sending to DLQ", {
          ...meta,
          error: err,
        });

        await producer.send({
          topic: DLQ_TOPIC,
          messages: [
            {
              key: message.key?.toString() || null,
              value: message.value,
              headers: {
                error: err.message,
                stack: err.stack || "",
                timestamp: Date.now().toString(),
                isRetry: "true",
              },
            },
          ],
        });
      }
    },
  });
};

runReactionWorker().catch((err: Error) => {
  logger.error("Reaction worker failed to start", { error: err });
  process.exit(1);
});
